package com.chanceman.account;

import com.chanceman.managers.RolledItemsManager;
import com.chanceman.managers.ObtainedItemsManager;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.AccountHashChanged;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Monitors for account changes and updates the stored display name.
 */
@Singleton
public class AccountManager
{
	@Inject
	private Client client;

	@Inject
	private ObtainedItemsManager obtainedItemsManager;
	@Inject
	private RolledItemsManager rolledItemsManager;

	@Inject
	private EventBus eventBus;

	private long hash = -1;
	@Getter @Setter private volatile String playerName;
	private boolean nameSet = false;

	public boolean ready() { return hash != -1 && nameSet; }

	public void init()
	{
		if (client.getGameState() == GameState.LOGGED_IN && client.getAccountHash() != -1)
		{
			hash = client.getAccountHash();
			nameSet = false;
		}
	}

	@Subscribe
	private void onAccountHashChanged(AccountHashChanged event)
	{
		long newHash = client.getAccountHash();
		if (hash != newHash)
		{
			hash = newHash;
			nameSet = false; // Player is null at this point, so name is set in onClientTick
		}
	}

	@Subscribe
	private void onClientTick(ClientTick event)
	{
		if (client.getGameState().getState() < GameState.LOADING.getState()) return;
		if (hash == -1) return;
		if (nameSet) return;

		Player player = client.getLocalPlayer();
		if (player == null) return;

		String name = player.getName();
		if (name == null) return;

		setPlayerName(name);
		nameSet = true;
		emit();
	}

	@Subscribe
	private void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN && hash != -1)
		{
			reset();
		}
	}

	public void reset() {
		hash = -1;
		setPlayerName(null);
		emit();
	}

	private void emit()
	{
		eventBus.post(new AccountChanged(hash, playerName));
	}
}

package com.chanceman.drops;

import static net.runelite.client.RuneLite.RUNELITE_DIR;

import com.chanceman.account.AccountManager;
import com.google.common.util.concurrent.ThreadFactoryBuilder;
import com.google.gson.Gson;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/**
 * Persistent drop table cache backed by JSON files in the user's RuneLite
 * directory. Exact NPC identities are cached by NPC ID so same-name/same-level
 * variants can never overwrite or satisfy one another.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class DropCache {
    private static final Duration MAX_AGE = Duration.ofDays(7);
    private static final Duration TEMP_FILE_MAX_AGE = Duration.ofDays(1);
    private static final String CACHE_DIRECTORY = "drops";
    private static final String EXACT_FILE_PREFIX = "npc_";
    private static final Pattern EXACT_CACHE_FILE = Pattern.compile("^npc_(\\d+)\\.json$");

    private final Gson gson;
    private final AccountManager accountManager;
    private final DropFetcher dropFetcher;

    private final Map<Path, NpcDropData> cache = new ConcurrentHashMap<>();
    private final Object indexLock = new Object();

    private volatile String loadedPlayer;
    private volatile boolean indexLoaded;
    private ExecutorService ioExecutor;

    private static int npcIdFromFilename(String filename) {
        Matcher matcher = EXACT_CACHE_FILE.matcher(Objects.toString(filename, ""));
        if (!matcher.matches()) {
            return -1;
        }
        try {
            return Integer.parseInt(matcher.group(1));
        } catch (NumberFormatException ex) {
            return -1;
        }
    }

    /**
     * Preload the current account's on-disk index and prune stale entries.
     */
    public void startUp() {
        ensureExecutor();
        String player = currentPlayer();
        if (player == null) {
            return;
        }

        ensureIndexForPlayer(player);
        pruneOldCaches();
    }

    /**
     * Fetch one NPC. Positive NPC IDs are exact identities and are cached by ID.
     * Name only lookups are intentionally not persisted because a name/level pair
     * is not guaranteed to identify one NPC variant.
     */
    public CompletableFuture<NpcDropData> get(int npcId, String name, int level) {
        String player = currentPlayer();
        CompletableFuture<NpcDropData> raw = npcId > 0 && player != null
                ? getOrFetchExactRaw(npcId, name, level, player)
                : dropFetcher.fetch(npcId, name, level);

        return raw.thenCompose(dropFetcher::resolveForDisplay)
                .exceptionally(ex -> {
                    log.error("Error fetching drop data for NPC {}", npcId, ex);
                    return null;
                });
    }

    /**
     * Fetch every distinct Wiki monster variant matching a page name and optional
     * combat level. Each result carries an exact NPC ID whenever the Wiki exposes
     * one, so two variants such as same-level armed/unarmed NPCs remain separate.
     */
    public CompletableFuture<List<NpcDropData>> searchNpcVariants(String name, int level) {
        return dropFetcher.fetchVariants(name, level)
                .thenCompose(this::resolveAllForDisplay)
                .exceptionally(ex ->
                {
                    log.error("Error fetching NPC variants for {} (lvl {})", name, level, ex);
                    return new ArrayList<>();
                });
    }

    /**
     * Persist exactly one NPC chosen from search results. Search results are
     * display copies, so use the same exact-ID raw-cache path as get(...) instead
     * of serializing the display copy. That preserves the raw Wiki rows on disk
     * and also reuses any fresh exact cache that already exists.
     */
    public CompletableFuture<Void> cacheSelected(NpcDropData selected) {
        if (selected == null || selected.getNpcId() <= 0) {
            return CompletableFuture.completedFuture(null);
        }

        String player = currentPlayer();
        if (player == null) {
            log.warn("Cannot cache selected NPC {} because player identity is unavailable", selected.getNpcId());
            return CompletableFuture.completedFuture(null);
        }

        int npcId = selected.getNpcId();
        return getOrFetchExactRaw(npcId, selected.getName(), selected.getLevel(), player)
                .thenApply(ignored -> (Void) null)
                .exceptionally(ex -> {
                    log.warn("Failed to persist selected NPC {}", npcId, ex);
                    return null;
                });
    }

    private CompletableFuture<NpcDropData> getOrFetchExactRaw(
            int npcId, String name, int level, String player) {
        ExecutorService executor = ensureExecutor();
        ensureIndexForPlayer(player);
        Path exactFile = getCacheFile(player, npcId);

        return CompletableFuture.supplyAsync(
                () -> readFreshCache(exactFile, player, npcId, level),
                executor
        ).thenComposeAsync(cached -> cached != null
                ? CompletableFuture.completedFuture(cached)
                : fetchAndCacheExact(npcId, name, level, player, exactFile, executor), executor);
    }

    private CompletableFuture<NpcDropData> fetchAndCacheExact(
            int npcId,
            String name,
            int level,
            String player,
            Path exactFile,
            ExecutorService executor) {
        return dropFetcher.fetch(npcId, name, level).thenApplyAsync(data ->
        {
            if (!isCacheable(data) || data.getNpcId() != npcId) {
                return null;
            }

            try {
                writeCacheFile(exactFile, data);
                if (player.equals(loadedPlayer) && indexLoaded) {
                    indexData(exactFile, data);
                }
            } catch (Exception ex) {
                log.error("Failed to write exact drop cache for NPC {}", npcId, ex);
            }
            return data;
        }, executor);
    }

    private CompletableFuture<List<NpcDropData>> resolveAllForDisplay(List<NpcDropData> raw) {
        if (raw == null || raw.isEmpty()) {
            return CompletableFuture.completedFuture(new ArrayList<>());
        }

        List<CompletableFuture<NpcDropData>> futures = raw.stream()
                .filter(Objects::nonNull)
                .map(dropFetcher::resolveForDisplay)
                .collect(Collectors.toList());

        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
                .thenApply(ignored -> futures.stream()
                        .map(CompletableFuture::join)
                        .filter(Objects::nonNull)
                        .filter(data -> data.getDropTableSections() != null
                                && !data.getDropTableSections().isEmpty())
                        .collect(Collectors.toList()));
    }

    /**
     * @return a snapshot of all exact cached NPC drop data for the current account.
     */
    public Collection<NpcDropData> getAllNpcData() {
        String player = currentPlayer();
        if (player == null) {
            return new ArrayList<>();
        }

        ensureIndexForPlayer(player);
        return new ArrayList<>(cache.values());
    }

    /**
     * Return NPC names containing the supplied query. Local exact-cache matches
     * are combined with Wiki search results.
     */
    public CompletableFuture<List<String>> searchNpcNames(String query) {
        ExecutorService executor = ensureExecutor();
        return CompletableFuture.supplyAsync(() ->
        {
            String search = Objects.toString(query, "").trim();
            String lowerSearch = search.toLowerCase(Locale.ROOT);

            String player = currentPlayer();
            if (player != null) {
                ensureIndexForPlayer(player);
            }

            Set<String> names = cache.values().stream()
                    .map(NpcDropData::getName)
                    .filter(Objects::nonNull)
                    .filter(candidate -> candidate.toLowerCase(Locale.ROOT).contains(lowerSearch))
                    .collect(Collectors.toCollection(LinkedHashSet::new));

            try {
                names.addAll(dropFetcher.searchNpcNames(search));
            } catch (Exception ex) {
                log.warn("Wiki search failed for {}", search, ex);
            }

            return new ArrayList<>(names);
        }, executor);
    }

    /**
     * Delete stale cache, legacy cache JSON, and abandoned temporary files.
     */
    public void pruneOldCaches() {
        String player = currentPlayer();
        if (player == null) {
            return;
        }

        ensureIndexForPlayer(player);
        Path directory = getCacheDir(player);
        if (!Files.isDirectory(directory)) {
            return;
        }

        Instant cacheCutoff = Instant.now().minus(MAX_AGE);
        Instant tempCutoff = Instant.now().minus(TEMP_FILE_MAX_AGE);

        try (Stream<Path> files = Files.list(directory)) {
            files.filter(Files::isRegularFile).forEach(path ->
            {
                try {
                    String filename = path.getFileName().toString();
                    Instant modified = Files.getLastModifiedTime(path).toInstant();

                    boolean legacyJson = filename.endsWith(".json") && npcIdFromFilename(filename) < 0;
                    boolean staleJson = filename.endsWith(".json") && modified.isBefore(cacheCutoff);
                    boolean staleTemp = filename.endsWith(".tmp") && modified.isBefore(tempCutoff);
                    if (legacyJson || staleJson || staleTemp) {
                        Files.deleteIfExists(path);
                        removeIndex(path);
                    }
                } catch (IOException ex) {
                    log.warn("Failed to prune drop cache {}", path, ex);
                }
            });
        } catch (IOException ex) {
            log.warn("Error pruning drop cache directory {}", directory, ex);
        }
    }

    /**
     * Delete all cached drop tables for the current player.
     */
    public void clearAllCaches() {
        String player = currentPlayer();
        if (player == null) {
            return;
        }

        synchronized (indexLock) {
            Path directory = getCacheDir(player);
            if (Files.isDirectory(directory)) {
                try (Stream<Path> files = Files.list(directory)) {
                    files.filter(Files::isRegularFile).forEach(path ->
                    {
                        try {
                            Files.deleteIfExists(path);
                        } catch (IOException ex) {
                            log.warn("Failed to delete drop cache {}", path, ex);
                        }
                    });
                } catch (IOException ex) {
                    log.warn("Error clearing drop cache directory {}", directory, ex);
                }
            }

            cache.clear();
            loadedPlayer = player;
            indexLoaded = true;
        }
    }

    /**
     * Gracefully stop cache IO and discard the in-memory account index.
     */
    public synchronized void shutdown() {
        ExecutorService executor = ioExecutor;
        if (executor != null) {
            executor.shutdownNow();
            ioExecutor = null;
        }

        synchronized (indexLock) {
            cache.clear();
            loadedPlayer = null;
            indexLoaded = false;
        }
    }

    private NpcDropData readFreshCache(Path file, String expectedPlayer, int expectedNpcId, int expectedLevel) {
        if (file == null || !Files.isRegularFile(file)) {
            if (file != null) {
                removeIndex(file);
            }
            return null;
        }

        if (!isFresh(file)) {
            deleteCacheFile(file);
            return null;
        }

        NpcDropData inMemory = cache.get(file);
        if (isValidExactCache(inMemory, expectedNpcId, expectedLevel)) {
            return inMemory;
        }

        try {
            NpcDropData data = readCacheFile(file);
            if (!isValidExactCache(data, expectedNpcId, expectedLevel)) {
                deleteCacheFile(file);
                return null;
            }

            if (expectedPlayer.equals(loadedPlayer) && indexLoaded) {
                indexData(file, data);
            }
            return data;
        } catch (Exception ex) {
            log.warn("Skipping bad cache file {}", file, ex);
            deleteCacheFile(file);
            return null;
        }
    }

    private boolean isValidExactCache(NpcDropData data, int expectedNpcId, int expectedLevel) {
        if (!isCacheable(data) || data.getNpcId() != expectedNpcId) {
            return false;
        }
        return expectedLevel <= 0 || data.getLevel() <= 0 || data.getLevel() == expectedLevel;
    }

    private void writeCacheFile(Path output, NpcDropData data) throws IOException {
        Files.createDirectories(output.getParent());
        Path temporary = Files.createTempFile(
                output.getParent(),
                output.getFileName().toString() + ".",
                ".tmp"
        );

        try {
            Files.writeString(
                    temporary,
                    gson.toJson(data),
                    StandardCharsets.UTF_8,
                    StandardOpenOption.TRUNCATE_EXISTING,
                    StandardOpenOption.WRITE
            );

            try {
                Files.move(
                        temporary,
                        output,
                        StandardCopyOption.REPLACE_EXISTING,
                        StandardCopyOption.ATOMIC_MOVE
                );
            } catch (AtomicMoveNotSupportedException | UnsupportedOperationException ex) {
                Files.move(temporary, output, StandardCopyOption.REPLACE_EXISTING);
            }
        } finally {
            Files.deleteIfExists(temporary);
        }
    }

    private NpcDropData readCacheFile(Path path) throws IOException {
        String json = Files.readString(path, StandardCharsets.UTF_8);
        return gson.fromJson(json, NpcDropData.class);
    }

    private boolean isCacheable(NpcDropData data) {
        return data != null
                && data.getDropTableSections() != null
                && !data.getDropTableSections().isEmpty();
    }

    private boolean isFresh(Path file) {
        try {
            Instant cutoff = Instant.now().minus(MAX_AGE);
            return !Files.getLastModifiedTime(file).toInstant().isBefore(cutoff);
        } catch (IOException ex) {
            return false;
        }
    }

    private void ensureIndexForPlayer(String player) {
        if (indexLoaded && player.equals(loadedPlayer)) {
            return;
        }

        synchronized (indexLock) {
            if (indexLoaded && player.equals(loadedPlayer)) {
                return;
            }

            if (!player.equals(loadedPlayer)) {
                cache.clear();
                loadedPlayer = player;
                indexLoaded = false;
            }

            Path directory = getCacheDir(player);
            if (!Files.exists(directory)) {
                indexLoaded = true;
                return;
            }

            try (Stream<Path> files = Files.list(directory)) {
                for (Path path : files
                        .filter(Files::isRegularFile)
                        .filter(candidate -> candidate.getFileName().toString().endsWith(".json"))
                        .collect(Collectors.toList())) {
                    String filename = path.getFileName().toString();
                    int expectedNpcId = npcIdFromFilename(filename);
                    if (expectedNpcId < 0 || !isFresh(path)) {
                        deleteCacheFile(path);
                        continue;
                    }
                    try {
                        NpcDropData data = readCacheFile(path);
                        if (isValidExactCache(data, expectedNpcId, 0)) {
                            indexData(path, data);
                        } else {
                            deleteCacheFile(path);
                        }
                    } catch (Exception ex) {
                        log.warn("Skipping bad cache file {}", path, ex);
                        deleteCacheFile(path);
                    }
                }
                indexLoaded = true;
            } catch (IOException ex) {
                log.warn("Error loading cache index for {}", player, ex);
            }
        }
    }

    private void indexData(Path path, NpcDropData data) {
        cache.put(path, data);
    }

    private void removeIndex(Path path) {
        cache.remove(path);
    }

    private void deleteCacheFile(Path path) {
        try {
            Files.deleteIfExists(path);
        } catch (IOException ex) {
            log.warn("Failed to delete drop cache {}", path, ex);
        }
        removeIndex(path);
    }

    private Path getCacheDir(String player) {
        return RUNELITE_DIR.toPath()
                .resolve("chanceman")
                .resolve(player)
                .resolve(CACHE_DIRECTORY);
    }

    private Path getCacheFile(String player, int npcId) {
        return getCacheDir(player).resolve(EXACT_FILE_PREFIX + npcId + ".json");
    }

    private String currentPlayer() {
        String player = Objects.toString(accountManager.getPlayerName(), "").trim();
        return player.isEmpty() ? null : player;
    }

    private synchronized ExecutorService ensureExecutor() {
        if (ioExecutor == null || ioExecutor.isShutdown() || ioExecutor.isTerminated()) {
            ioExecutor = Executors.newFixedThreadPool(
                    2,
                    new ThreadFactoryBuilder().setNameFormat("dropcache-io-%d").build()
            );
        }
        return ioExecutor;
    }
}

package com.chanceman.drops;

import com.google.common.util.concurrent.ThreadFactoryBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import lombok.RequiredArgsConstructor;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.http.api.item.ItemPrice;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.StringJoiner;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * Retrieves exact NPC drop data from the OSRS Wiki Bucket API.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class DropFetcher {
    private static final String USER_AGENT = "RuneLite-ChanceMan";
    private static final String WIKI_API = "https://oldschool.runescape.wiki/api.php";
    private static final int ITEM_SCAN_LIMIT = 40_000;

    private final OkHttpClient httpClient;
    private final ItemManager itemManager;
    private final ClientThread clientThread;

    private final Map<String, WikiPageMetadata> metadataCache = new ConcurrentHashMap<>();
    private final Map<String, List<WikiDropBucketParser.BucketDrop>> dropRowsCache = new ConcurrentHashMap<>();
    private final Map<String, Integer> itemIdByName = new ConcurrentHashMap<>();
    private final Map<String, Integer> allItemIdByName = new ConcurrentHashMap<>();

    private volatile boolean itemIndexReady;
    private ExecutorService fetchExecutor;

    private static String variantIdentity(
            WikiMonsterMetadataParser.Variant variant,
            int npcId,
            int level) {
        if (npcId > 0) {
            return "id:" + npcId;
        }

        return "variant:"
                + WikiMonsterMetadataParser.normalizeForComparison(variant.getVersion())
                + "|drops:" + String.join(",", effectiveDropVersions(variant))
                + "|level:" + level;
    }

    private static NpcDropData copyForDisplay(NpcDropData source) {
        List<DropTableSection> sections = new ArrayList<>();
        for (DropTableSection section : source.getDropTableSections()) {
            List<DropItem> items = new ArrayList<>();
            for (DropItem item : section.getItems()) {
                items.add(new DropItem(0, item.getName(), item.getRarity()));
            }
            sections.add(new DropTableSection(section.getHeader(), items));
        }
        return new NpcDropData(source.getNpcId(), source.getName(), source.getLevel(), sections);
    }

    private static void indexItemName(Map<String, Integer> index, String name, int itemId) {
        String key = normalizeItemName(name);
        if (!key.isEmpty() && !"null".equals(key) && !"members object".equals(key)) {
            index.merge(key, itemId, Math::min);
        }
    }

    private static List<String> effectiveDropVersions(WikiMonsterMetadataParser.Variant variant) {
        if (variant == null) {
            return Collections.emptyList();
        }

        List<String> versions = new ArrayList<>(variant.getDropVersions());
        versions.addAll(variant.getSubNames());
        return versions;
    }

    private static int firstNpcId(WikiMonsterMetadataParser.Variant variant) {
        return variant == null || variant.getNpcIds().isEmpty()
                ? 0
                : variant.getNpcIds().iterator().next();
    }

    private static JsonObject firstQueryPage(String responseBody) {
        JsonElement parsed = new JsonParser().parse(responseBody);
        if (!parsed.isJsonObject()) {
            return null;
        }

        JsonObject query = parsed.getAsJsonObject().getAsJsonObject("query");
        JsonArray pages = query == null ? null : query.getAsJsonArray("pages");
        return pages == null || pages.size() == 0 || !pages.get(0).isJsonObject()
                ? null
                : pages.get(0).getAsJsonObject();
    }

    private static JsonArray bucketRows(String responseBody) {
        JsonElement parsed = new JsonParser().parse(responseBody);
        if (!parsed.isJsonObject()) {
            return new JsonArray();
        }

        JsonObject root = parsed.getAsJsonObject();
        String error = WikiDropBucketParser.stringValue(root.get("error"));
        if (!error.isEmpty()) {
            throw new IllegalArgumentException("Wiki Bucket query failed: " + error);
        }

        JsonElement bucket = root.get("bucket");
        return bucket != null && bucket.isJsonArray() ? bucket.getAsJsonArray() : new JsonArray();
    }

    private static String apiUrl(String... parameters) {
        if (parameters.length % 2 != 0) {
            throw new IllegalArgumentException("API parameters must be key/value pairs");
        }

        StringJoiner query = new StringJoiner("&", WIKI_API + "?", "");
        query.add(parameter("format", "json"));
        query.add(parameter("formatversion", "2"));
        for (int i = 0; i < parameters.length; i += 2) {
            query.add(parameter(parameters[i], parameters[i + 1]));
        }
        return query.toString();
    }

    private static String parameter(String key, String value) {
        return URLEncoder.encode(key, StandardCharsets.UTF_8)
                + "="
                + URLEncoder.encode(Objects.toString(value, ""), StandardCharsets.UTF_8);
    }

    private static String luaString(String value) {
        String escaped = Objects.toString(value, "")
                .replace("\\", "\\\\")
                .replace("\"", "\\\"")
                .replace("\r", "\\r")
                .replace("\n", "\\n");
        return "\"" + escaped + "\"";
    }


    private static boolean sameWikiName(String left, String right) {
        return normalizeWikiName(left).equals(normalizeWikiName(right));
    }

    private static String normalizeWikiName(String value) {
        return sanitizeName(value)
                .replace('_', ' ')
                .replaceAll("\\s+", " ")
                .toLowerCase(Locale.ROOT);
    }

    private static String sanitizeName(String value) {
        return value == null ? "" : value.trim();
    }


    private static List<String> itemNameCandidates(String wikiName) {
        String exact = wikiName == null ? "" : wikiName.trim();
        if (exact.isEmpty()) {
            return Collections.emptyList();
        }

        Map<String, String> candidates = new LinkedHashMap<>();
        candidates.put(normalizeItemName(exact), exact);

        int anchor = exact.indexOf('#');
        if (anchor >= 0) {
            String withoutAnchor = exact.replace("#", "");
            String spacedAnchor = exact.replace("#", " ");
            String beforeAnchor = exact.substring(0, anchor).trim();
            candidates.putIfAbsent(normalizeItemName(withoutAnchor), withoutAnchor);
            candidates.putIfAbsent(normalizeItemName(spacedAnchor), spacedAnchor);
            candidates.putIfAbsent(normalizeItemName(beforeAnchor), beforeAnchor);
        }
        candidates.remove("");
        return new ArrayList<>(candidates.values());
    }

    private static String normalizeItemName(String itemName) {
        return itemName == null
                ? ""
                : itemName
                .replace('\u00A0', ' ')
                .replace('\u2018', '\'')
                .replace('\u2019', '\'')
                .replace('_', ' ')
                .replaceAll("\\s+", " ")
                .trim()
                .toLowerCase(Locale.ROOT);
    }

    /**
     * Fetch raw Wiki drop rows. Item IDs are resolved only on the display copy.
     */
    public CompletableFuture<NpcDropData> fetch(int npcId, String name, int level) {
        return CompletableFuture.supplyAsync(
                () -> fetchDropData(npcId, name, level),
                ensureExecutor()
        );
    }

    /**
     * Fetch every distinct Wiki monster variant for a page and optional combat
     * level. This is the search path: it deliberately returns multiple results
     * when level alone is ambiguous, with each result carrying a concrete NPC ID.
     */
    public CompletableFuture<List<NpcDropData>> fetchVariants(String name, int level) {
        return CompletableFuture.supplyAsync(
                () -> fetchVariantDropData(name, level),
                ensureExecutor()
        );
    }

    private List<NpcDropData> fetchVariantDropData(String name, int level) {
        NpcPageReference page = resolveNpcPage(0, name);
        if (page == null || page.getPageName().isEmpty()) {
            return Collections.emptyList();
        }

        WikiPageMetadata metadata = loadMetadata(page.getPageName());
        List<WikiMonsterMetadataParser.Variant> variants = metadata.getMonster().selectVariants(level);
        if (variants.isEmpty()) {
            if (level > 0) {
                return Collections.emptyList();
            }

            NpcDropData fallback = fetchDropData(0, page.getPageName(), 0);
            return fallback == null
                    ? Collections.emptyList()
                    : Collections.singletonList(fallback);
        }

        List<WikiDropBucketParser.BucketDrop> rows = loadDropRows(page.getPageName());
        Map<String, NpcDropData> distinct = new LinkedHashMap<>();

        for (WikiMonsterMetadataParser.Variant variant : variants) {
            int resolvedLevel = variant.getCombatLevel() > 0 ? variant.getCombatLevel() : level;
            if (level > 0 && resolvedLevel != level) {
                continue;
            }

            int resolvedNpcId = firstNpcId(variant);
            NpcDropData data = buildDropData(
                    page.getPageName(), metadata, rows, variant, resolvedNpcId, resolvedLevel);
            if (data != null) {
                distinct.putIfAbsent(variantIdentity(variant, resolvedNpcId, resolvedLevel), data);
            }
        }

        return new ArrayList<>(distinct.values());
    }

    private NpcDropData fetchDropData(int npcId, String name, int level) {
        NpcPageReference page = resolveNpcPage(npcId, name);
        if (page == null || page.getPageName().isEmpty()) {
            return null;
        }

        WikiPageMetadata metadata = loadMetadata(page.getPageName());
        WikiMonsterMetadataParser.Variant variant = metadata.getMonster()
                .selectVariant(npcId, level, page.getPageSub());

        if (npcId <= 0 && level > 0) {
            if (variant == null
                    || (variant.getCombatLevel() > 0 && variant.getCombatLevel() != level)) {
                return null;
            }
        }

        return buildDropData(
                page.getPageName(), metadata, loadDropRows(page.getPageName()), variant, npcId, level);
    }

    private NpcDropData buildDropData(
            String pageName,
            WikiPageMetadata metadata,
            List<WikiDropBucketParser.BucketDrop> rows,
            WikiMonsterMetadataParser.Variant variant,
            int npcId,
            int level) {
        int resolvedLevel = level > 0 ? level : variant == null ? 0 : variant.getCombatLevel();
        int resolvedNpcId = npcId > 0 ? npcId : firstNpcId(variant);
        List<String> dropVersions = new ArrayList<>(effectiveDropVersions(variant));

        Set<String> locationVersions = metadata.getLocationDropVersionsByLevel()
                .getOrDefault(resolvedLevel, Collections.emptySet());

        if (locationVersions.size() == 1) {
            dropVersions.add(locationVersions.iterator().next());
        }

        List<DropTableSection> sections = WikiDropBucketParser.selectSections(
                rows,
                dropVersions,
                resolvedLevel,
                metadata.getDropTableClassification()
        );
        return sections.isEmpty()
                ? null
                : new NpcDropData(resolvedNpcId, pageName, resolvedLevel, sections);
    }

    /**
     * Create a display-only copy, resolve GE-tradeable item IDs on the client
     * thread, and remove unresolved/untradeable rows. The raw cached data is
     * never mutated, so a temporarily unavailable item index cannot permanently
     * erase sections from disk.
     */
    CompletableFuture<NpcDropData> resolveForDisplay(NpcDropData source) {
        if (source == null) {
            return CompletableFuture.completedFuture(null);
        }

        NpcDropData display = copyForDisplay(source);
        CompletableFuture<NpcDropData> future = new CompletableFuture<>();
        clientThread.invoke(() ->
        {
            try {
                ensureItemIndex();

                for (DropTableSection section : display.getDropTableSections()) {
                    boolean specialTable = WikiDropBucketParser.isSpecialSection(section.getHeader());
                    for (DropItem item : section.getItems()) {
                        item.setItemId(specialTable
                                ? resolveAnyItemId(item.getName())
                                : resolveItemId(item.getName()));
                    }
                    section.getItems().removeIf(item -> item.getItemId() <= 0);
                }
                display.getDropTableSections().removeIf(section -> section.getItems().isEmpty());
                future.complete(display.getDropTableSections().isEmpty() ? null : display);
            } catch (Throwable ex) {
                future.completeExceptionally(ex);
            }
        });
        return future;
    }

    /**
     * Build the GE-tradeable index used by Chance Man's normal item pool plus a
     * complete canonical item-definition index for Wiki-generated special tables.
     * No RDT/GDT item IDs are hardcoded.
     */
    private void ensureItemIndex() {
        if (itemIndexReady) {
            return;
        }

        Map<String, Integer> tradeableIndex = new HashMap<>();
        Map<String, Integer> allIndex = new HashMap<>();
        for (int itemId = 0; itemId < ITEM_SCAN_LIMIT; itemId++) {
            try {
                ItemComposition item = itemManager.getItemComposition(itemId);
                if (item == null
                        || item.getNote() != -1
                        || item.getPlaceholderTemplateId() != -1) {
                    continue;
                }

                int canonicalId = itemManager.canonicalize(itemId);
                indexItemName(allIndex, item.getMembersName(), canonicalId);
                indexItemName(allIndex, item.getName(), canonicalId);

                if (item.isGeTradeable()) {
                    indexItemName(tradeableIndex, item.getMembersName(), canonicalId);
                    indexItemName(tradeableIndex, item.getName(), canonicalId);
                }
            } catch (RuntimeException ignored) {
            }
        }

        if (tradeableIndex.isEmpty() || allIndex.isEmpty()) {
            log.warn("RuneLite item definitions are not ready; item indexes will retry");
            return;
        }

        itemIdByName.clear();
        itemIdByName.putAll(tradeableIndex);
        allItemIdByName.clear();
        allItemIdByName.putAll(allIndex);
        itemIndexReady = true;
        log.warn(
                "Indexed {} GE-tradeable and {} total RuneScape item names",
                tradeableIndex.size(),
                allIndex.size()
        );
    }

    private static Map<Integer, Set<String>> locationDropVersionsByLevel(String wikitext) {
        Map<Integer, Set<String>> byLevel = new LinkedHashMap<>();

        for (WikiTemplateParser.Template location
                : WikiTemplateParser.findAll(wikitext, "LocLine")) {

            String version = sanitizeName(location.get("dropversion"));
            if (version.isEmpty()) {
                continue;
            }

            String levels = location.get("levels");
            if (levels.isEmpty()) {
                levels = location.get("level");
            }

            for (int level : WikiMonsterMetadataParser.parseIntegers(levels)) {
                byLevel.computeIfAbsent(level, ignored -> new LinkedHashSet<>())
                        .add(version);
            }
        }

        return byLevel;
    }

    private WikiPageMetadata loadMetadata(String pageName) {
        try {
            return metadataCache.computeIfAbsent(pageName, key -> {
                String wikitext = fetchRawWikitext(key);
                return new WikiPageMetadata(
                        WikiMonsterMetadataParser.parse(wikitext),
                        WikiDropTableClassifier.parse(wikitext),
                        locationDropVersionsByLevel(wikitext)
                );
            });
        } catch (RuntimeException ex) {
            log.warn("Could not load monster metadata for {}", pageName, ex);
            return WikiPageMetadata.empty();
        }
    }

    private List<WikiDropBucketParser.BucketDrop> loadDropRows(String pageName) {
        return dropRowsCache.computeIfAbsent(pageName, key -> {
            String query = "bucket('dropsline')"
                    + ".select('page_name','page_name_sub','drop_json','rare_drop_table')"
                    + ".where('page_name'," + luaString(key) + ")"
                    + ".limit(5000).run()";
            return Collections.unmodifiableList(
                    new ArrayList<>(WikiDropBucketParser.parseResponse(executeBucketQuery(query)))
            );
        });
    }

    private NpcPageReference resolveNpcPage(int npcId, String suppliedName) {
        String name = sanitizeName(suppliedName);
        if (npcId > 0) {
            try {
                NpcPageReference page = resolveNpcPageFromBucket(npcId, name);
                if (page != null) {
                    return page;
                }
            } catch (RuntimeException ex) {
                log.warn("NPC ID Bucket lookup failed for {}", npcId, ex);
            }
        }
        return name.isEmpty() ? null : new NpcPageReference(resolveCanonicalTitle(name), "");
    }

    private NpcPageReference resolveNpcPageFromBucket(int npcId, String suppliedName) {
        String query = "bucket('npc_id')"
                + ".select('page_name','page_name_sub')"
                + ".where('id'," + npcId + ")"
                + ".limit(20).run()";

        NpcPageReference first = null;
        for (JsonElement element : bucketRows(executeBucketQuery(query))) {
            if (!element.isJsonObject()) {
                continue;
            }

            JsonObject row = element.getAsJsonObject();
            String pageName = WikiDropBucketParser.stringValue(row.get("page_name"));
            if (pageName.isEmpty()) {
                continue;
            }

            NpcPageReference candidate = new NpcPageReference(
                    pageName,
                    WikiDropBucketParser.extractPageSub(pageName, WikiDropBucketParser.stringValue(row.get("page_name_sub")))
            );
            if (first == null) {
                first = candidate;
            }
            if (!suppliedName.isEmpty() && sameWikiName(pageName, suppliedName)) {
                return candidate;
            }
        }
        return first;
    }

    private String resolveCanonicalTitle(String title) {
        JsonObject page = firstQueryPage(executeGet(apiUrl(
                "action", "query",
                "redirects", "1",
                "titles", title
        )));
        String canonical = page == null ? "" : WikiDropBucketParser.stringValue(page.get("title"));
        return canonical.isEmpty() ? title : canonical;
    }

    private String fetchRawWikitext(String pageName) {
        JsonObject page = firstQueryPage(executeGet(apiUrl(
                "action", "query",
                "redirects", "1",
                "prop", "revisions",
                "titles", pageName,
                "rvprop", "content",
                "rvslots", "main"
        )));
        if (page == null) {
            return "";
        }

        JsonArray revisions = page.getAsJsonArray("revisions");
        if (revisions == null || revisions.size() == 0 || !revisions.get(0).isJsonObject()) {
            return "";
        }

        JsonObject revision = revisions.get(0).getAsJsonObject();
        JsonObject slots = revision.getAsJsonObject("slots");
        JsonObject main = slots == null ? null : slots.getAsJsonObject("main");
        if (main != null) {
            String content = WikiDropBucketParser.stringValue(main.get("content"));
            return content.isEmpty() ? WikiDropBucketParser.stringValue(main.get("*")) : content;
        }
        return WikiDropBucketParser.stringValue(revision.get("*"));
    }

    private String executeBucketQuery(String query) {
        return executeGet(apiUrl("action", "bucket", "query", query));
    }

    private String executeGet(String url) {
        Request request = new Request.Builder()
                .url(url)
                .header("User-Agent", USER_AGENT)
                .build();

        try (Response response = httpClient.newCall(request).execute()) {
            if (!response.isSuccessful()) {
                throw new IOException("HTTP " + response.code() + " for " + response.request().url());
            }
            ResponseBody body = response.body();
            if (body == null) {
                throw new IOException("Empty response body for " + response.request().url());
            }
            return body.string();
        } catch (IOException ex) {
            throw new UncheckedIOException(ex);
        }
    }

    /**
     * Resolve any concrete RuneLite item by its Wiki display name.
     */
    private int resolveAnyItemId(String wikiName) {
        for (String candidate : itemNameCandidates(wikiName)) {
            Integer cached = allItemIdByName.get(normalizeItemName(candidate));
            if (cached != null && cached > 0) {
                return cached;
            }
        }

        return resolveItemId(wikiName);
    }

    /**
     * Resolve only player-tradeable items through RuneLite's item-price search.
     */
    private int resolveItemId(String wikiName) {
        for (String candidate : itemNameCandidates(wikiName)) {
            String key = normalizeItemName(candidate);
            Integer cached = itemIdByName.get(key);
            if (cached != null) {
                return cached;
            }

            int resolved = searchTradeableItem(candidate, key);
            if (resolved > 0) {
                itemIdByName.put(key, resolved);
                return resolved;
            }
        }
        return 0;
    }

    private int searchTradeableItem(String candidate, String normalizedCandidate) {
        try {
            List<ItemPrice> results = itemManager.search(candidate);
            if (results == null) {
                return 0;
            }

            for (ItemPrice result : results) {
                ItemComposition item = itemManager.getItemComposition(result.getId());
                if (item == null || !item.isGeTradeable()) {
                    continue;
                }

                String itemName = item.getMembersName();
                if (itemName == null || itemName.trim().isEmpty()) {
                    itemName = item.getName();
                }

                if (normalizedCandidate.equals(normalizeItemName(itemName))) {
                    return itemManager.canonicalize(result.getId());
                }
            }
        } catch (RuntimeException ex) {
            log.warn("Could not resolve Wiki drop item {}", candidate, ex);
        }
        return 0;
    }

    public List<String> searchNpcNames(String query) {
        JsonArray response = new JsonParser().parse(executeGet(apiUrl(
                "action", "opensearch",
                "limit", "20",
                "namespace", "0",
                "search", query == null ? "" : query
        ))).getAsJsonArray();

        if (response.size() < 2 || !response.get(1).isJsonArray()) {
            return Collections.emptyList();
        }

        List<String> names = new ArrayList<>();
        for (JsonElement title : response.get(1).getAsJsonArray()) {
            names.add(title.getAsString());
        }
        return names;
    }

    public void startUp() {
        ensureExecutor();
    }

    private synchronized ExecutorService ensureExecutor() {
        if (fetchExecutor == null || fetchExecutor.isShutdown() || fetchExecutor.isTerminated()) {
            fetchExecutor = Executors.newFixedThreadPool(
                    4,
                    new ThreadFactoryBuilder().setNameFormat("dropfetch-%d").build()
            );
        }
        return fetchExecutor;
    }

    public synchronized void shutdown() {
        if (fetchExecutor != null) {
            fetchExecutor.shutdownNow();
            fetchExecutor = null;
        }
        metadataCache.clear();
        dropRowsCache.clear();
        itemIdByName.clear();
        allItemIdByName.clear();
        itemIndexReady = false;
    }

    @Value
    private static class WikiPageMetadata {
        WikiMonsterMetadataParser.ParsedMonster monster;
        WikiDropTableClassifier.Classification dropTableClassification;
        Map<Integer, Set<String>> locationDropVersionsByLevel;

        static WikiPageMetadata empty() {
            return new WikiPageMetadata(
                    WikiMonsterMetadataParser.ParsedMonster.empty(),
                    WikiDropTableClassifier.Classification.empty(),
                    Collections.emptyMap()
            );
        }
    }

    @Value
    private static class NpcPageReference {
        String pageName;
        String pageSub;

        NpcPageReference(String pageName, String pageSub) {
            this.pageName = sanitizeName(pageName);
            this.pageSub = sanitizeName(pageSub);
        }
    }
}

package com.chanceman.drops;

import lombok.AllArgsConstructor;
import lombok.Getter;
import lombok.Setter;

import java.util.Arrays;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

@Setter
@Getter
@AllArgsConstructor
public class DropItem {
    // Anchored patterns for correctness & speed
    private static final Pattern PCT = Pattern.compile("^(\\d+(?:\\.\\d+)?)%$");
    private static final Pattern MULT = Pattern.compile("^(\\d+(?:\\.\\d+)?)\\s*[xX]\\s*(\\d+(?:\\.\\d+)?)\\s*/\\s*(\\d+(?:\\.\\d+)?)$");
    private static final Pattern FRAC = Pattern.compile("^(\\d+(?:\\.\\d+)?)\\s*/\\s*(\\d+(?:\\.\\d+)?)$");
    private static final Pattern PAREN = Pattern.compile("\\s*\\([^)]*\\)$", Pattern.UNICODE_CASE);
    private static final Pattern IN_SYNT = Pattern.compile("\\bin\\b", Pattern.CASE_INSENSITIVE);
    private static final Pattern BRACKETS = Pattern.compile("\\[[^\\]]*\\]");
    private static final Pattern ONE_OVER = Pattern.compile("1/(\\d+(?:\\.\\d+)?)");
    private int itemId;
    private String name;
    private String rarity;

    /**
     * Convert raw rarity to normalized one-over form (preserves ranges like “1/64–1/32”).
     */
    public String getOneOverRarity() {
        if (rarity == null) return "";
        String[] parts = rarity.split("\\s*;\\s*|,\\s+");
        return Arrays.stream(parts)
                .map(this::normalizeSegment)
                .collect(Collectors.joining("; "));
    }

    /**
     * Parse rarity and return the denominator (e.g., “1/128” -> 128).
     * Unknown values sort as rarest (POSITIVE_INFINITY). “Always” -> 0.
     */
    public double getRarityValue() {
        String oneOver = getOneOverRarity();
        if (oneOver.isEmpty()) {
            return Double.POSITIVE_INFINITY;
        }

        Matcher m = ONE_OVER.matcher(oneOver);
        if (m.find()) {
            try {
                return Double.parseDouble(m.group(1));
            } catch (NumberFormatException ignored) {
                return Double.POSITIVE_INFINITY;
            }
        }

        if (oneOver.equalsIgnoreCase("Always")) {
            return 0d;
        }

        return Double.POSITIVE_INFINITY;
    }

    private String normalizeSegment(String raw) {
        String cleaned = raw == null ? "" : raw;
        cleaned = BRACKETS.matcher(cleaned).replaceAll("");
        cleaned = cleaned
                .replace("×", "x")
                .replace(",", "")
                .replace("≈", "")
                .replace("~", "")
                .replaceAll(PAREN.pattern(), "")
                .replaceAll(IN_SYNT.pattern(), "/")
                .trim();

        // Handle ranges like "1/128 – 1/64"
        String[] range = cleaned.split("\\s*[–—-]\\s*");
        if (range.length > 1) {
            return Arrays.stream(range)
                    .map(this::simplifySingle)
                    .collect(Collectors.joining("–"));
        }

        return simplifySingle(cleaned);
    }

    private String simplifySingle(String s) {
        if (s == null || s.isEmpty()) {
            return "";
        }

        Matcher m;

        // 12.5%
        m = PCT.matcher(s);
        if (m.matches()) {
            double pct = safeDouble(m.group(1));
            if (pct == 0) return "0";
            return formatOneOver(100.0 / pct);
        }

        // 2 x 1 / 128
        m = MULT.matcher(s);
        if (m.matches()) {
            double factor = safeDouble(m.group(1));
            double a = safeDouble(m.group(2));
            double b = safeDouble(m.group(3));
            if (factor != 0 && a != 0) {
                return formatOneOver(b / (a * factor));
            }
        }

        // 1/128
        m = FRAC.matcher(s);
        if (m.matches()) {
            double a = safeDouble(m.group(1));
            double b = safeDouble(m.group(2));
            if (a != 0) {
                return formatOneOver(b / a);
            }
        }

        // fallback to cleaned input
        return s;
    }

    private double safeDouble(String s) {
        try {
            return Double.parseDouble(s);
        } catch (Exception e) {
            return Double.NaN;
        }
    }

    private String formatOneOver(double val) {
        if (Double.isNaN(val) || Double.isInfinite(val)) {
            return "";
        }
        if (Math.abs(val - Math.round(val)) < 0.01) {
            return "1/" + Math.round(val);
        }
        return String.format(Locale.ROOT, "1/%.2f", val);
    }
}

