    public static Set<Integer> getAllFlatpackIds() {
        Set<Integer> ids = new HashSet<>();
        for (Flatpacks fp : Flatpacks.values()) {
            ids.add(fp.getId());
        }
        return Collections.unmodifiableSet(ids);
    }

