            ItemID.XBOWS_CROSSBOW_BOLTS_ADAMANTITE_POISONED_, ItemID.XBOWS_CROSSBOW_BOLTS_ADAMANTITE_POISONED__),
    RUNITE_BOLTS(ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE, ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE_POISONED,
            ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE_POISONED_, ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE_POISONED__),
    DRAGON_BOLTS(ItemID.DRAGON_BOLTS, ItemID.DRAGON_BOLTS_P, ItemID.DRAGON_BOLTS_P_, ItemID.DRAGON_BOLTS_P__);

    private final int baseId;
    private final int poisonId;
    private final int poisonPlusId;
    private final int poisonPlusPlusId;

    // Overloaded constructor for global prerequisites
    PoisonWeapons(int id) {
        this.baseId = id;
        this.poisonId = id;
        this.poisonPlusId = id;
        this.poisonPlusPlusId = id;
    }

    // Constructor for weapons with distinct variant IDs.
    PoisonWeapons(int baseId, int poisonId, int poisonPlusId, int poisonPlusPlusId) {
        this.baseId = baseId;
        this.poisonId = poisonId;
        this.poisonPlusId = poisonPlusId;
        this.poisonPlusPlusId = poisonPlusPlusId;
    }

    /**
     * Checks whether the given item id matches any variant of this weapon.
     *
     * @param id the item id to check.
     * @return true if the id matches base, poison, poison+ or poison++.
     */
    public boolean matches(int id) {
        return id == baseId || id == poisonId || id == poisonPlusId || id == poisonPlusPlusId;
    }

    /**
     * Returns an unmodifiable set of all base weapon ids from poisonable weapons, excluding poison constants.
     */
    public static Set<Integer> getAllBaseWeaponIds() {
        Set<Integer> ids = new HashSet<>();
        for (PoisonWeapons weapon : values()) {
            if (!weapon.name().startsWith("WEAPON_POISON")) {
                ids.add(weapon.getBaseId());
            }
        }
        return Collections.unmodifiableSet(ids);
    }

    /**
     * Checks if a given item id is a poisonable weapon variant.
     *
     * @param itemId the item id to check.
     * @return true if it matches any poisonable weapon variant.
     */
    public static boolean isPoisonableWeapon(int itemId) {
        for (PoisonWeapons weapon : values()) {
            if (weapon.name().startsWith("WEAPON_POISON")) continue;
            if (weapon.matches(itemId)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if a poisonable weapon variant is eligible.
     * Base weapons are always eligible.
     * For poisoned variants:
     *   - (p) requires WEAPON_POISON,
     *   - (p+) requires WEAPON_POISON_,
     *   - (p++) requires WEAPON_POISON__,
     * to be unlocked along with the base weapon.
     * @param itemId the item ID to check
     * @param requireWeaponPoison if true, the corresponding global poison must be unlocked
     * @param unlockedItems the set of unlocked item IDs
     * @return true if eligible; false otherwise
     */
    public static boolean isPoisonVariantEligible(int itemId, boolean requireWeaponPoison, Set<Integer> unlockedItems) {
        PoisonWeapons matchingWeapon = null;
        for (PoisonWeapons weapon : values()) {
            if (weapon.name().startsWith("WEAPON_POISON")) continue;
            if (weapon.matches(itemId)) {
                matchingWeapon = weapon;
                break;
            }
        }
        if (matchingWeapon == null) {
            return true;
        }
        // Base weapon is always eligible.
        if (itemId == matchingWeapon.getBaseId()) {
            return true;
        }
        if (!requireWeaponPoison) {
            return true;
        }
        int requiredGlobalId;
        if (itemId == matchingWeapon.getPoisonId()) {
            requiredGlobalId = PoisonWeapons.WEAPON_POISON.getBaseId();
        } else if (itemId == matchingWeapon.getPoisonPlusId()) {
            requiredGlobalId = PoisonWeapons.WEAPON_POISON_.getBaseId();
        } else if (itemId == matchingWeapon.getPoisonPlusPlusId()) {
            requiredGlobalId = PoisonWeapons.WEAPON_POISON__.getBaseId();
        } else {
            return true;
        }
        boolean eligible = unlockedItems.contains(matchingWeapon.getBaseId()) && unlockedItems.contains(requiredGlobalId);
        return eligible;
    }

}

package com.chanceman.managers;

import com.chanceman.account.AccountManager;
import com.chanceman.persist.ConfigPersistence;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.Reader;
import java.lang.reflect.Type;
import java.nio.file.*;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.concurrent.ExecutorService;

import static net.runelite.client.RuneLite.RUNELITE_DIR;

@Slf4j
@Singleton
public class ObtainedItemsManager
{
    private static final int MAX_BACKUPS = 10;
    private static final String CFG_KEY = "obtained";
    private static final String FILE_NAME = "chanceman_obtained.json";
    private static final String LEGACY_CFG_KEY = "rolled";
    private static final String LEGACY_FILE_NAME = "chanceman_rolled.json";
    private static final String LEGACY_UNLOCKED_FILE = "chanceman_unlocked.json";
    private static final String BACKUP_TS_PATTERN = "yyyyMMddHHmmss";
    private static final long CONFIG_DEBOUNCE_MS = 3000L;
    private static final long SELF_WRITE_GRACE_MS = 1500L;
    private static final long FS_DEBOUNCE_MS = 200L;
    private static final Type SET_TYPE = new TypeToken<Set<Integer>>(){}.getType();
    private final Set<Integer> obtainedItems = Collections.synchronizedSet(new LinkedHashSet<>());

    @Inject private AccountManager accountManager;
    @Inject private Gson gson;
    @Inject private ConfigPersistence configPersistence;

    @Setter private ExecutorService executor; // file writes & cloud mirror
    @Setter private Runnable onChange;

    private volatile long lastConfigWriteMs = 0L;
    private volatile boolean configWriteWarned = false;
    private volatile boolean dirty = false;

    private WatchService watchService;
    private volatile boolean watcherRunning = false;
    private volatile long lastSelfWriteMs = 0L;
    private Thread watcherThread;

    public boolean isObtained(int itemId) { return obtainedItems.contains(itemId); }

    /** Return an immutable snapshot to avoid leaking the synchronizedSet. */
    public Set<Integer> getObtainedItems()
    {
        synchronized (obtainedItems)
        {
            return Collections.unmodifiableSet(new LinkedHashSet<>(obtainedItems));
        }
    }

    public void markObtained(int itemId)
    {
        if (obtainedItems.add(itemId))
        {
            dirty = true;
            saveObtainedItems();
            safeNotifyChange();
        }
    }

    public void loadObtainedItems()
    {
        reconcileWithCloud(false);
        safeNotifyChange();
    }

    /** Normal save: disk + debounced cloud with current time. */
    public void saveObtainedItems()
    {
        saveInternal(System.currentTimeMillis(), true);
    }

    /** Live-reload: start watching the JSON for CREATE/MODIFY/DELETE. */
    public void startWatching()
    {
        if (watcherRunning) return;
        Path file = safeGetFilePathOrNull(FILE_NAME);
        if (file == null) return;

        try
        {
            watchService = FileSystems.getDefault().newWatchService();
            file.getParent().register(
                    watchService,
                    StandardWatchEventKinds.ENTRY_CREATE,
                    StandardWatchEventKinds.ENTRY_MODIFY,
                    StandardWatchEventKinds.ENTRY_DELETE
            );
        }
        catch (IOException e)
        {
            closeWatchServiceQuietly();
            log.error("Obtained watcher: could not register", e);
            return;
        }

        watcherRunning = true;
        final String target = file.getFileName().toString();
        watcherThread = new Thread(() -> runWatcherLoop(target), "ChanceMan-Obtained-Watcher");
        watcherThread.setDaemon(true);
        watcherThread.start();
    }

    public void stopWatching()
    {
        watcherRunning = false;
        closeWatchServiceQuietly();
        watcherThread = null;
    }

    /** Flush synchronously on shutdown if dirty. */
    public void flushIfDirtyOnExit()
    {
        if (!dirty) return;
        Path file = safeGetFilePathOrNull(FILE_NAME);
        if (file == null) return;

        try
        {
            rotateBackupIfExists(file);
            Set<Integer> snap = snapshotObtained();
            writeJsonAtomic(file, snap);
            mirrorToCloud(System.currentTimeMillis(), false, snap);
            dirty = false;
        }
        catch (IOException e)
        {
            log.error("Shutdown flush failed for obtained items (local saves may be stale).", e);
        }
        catch (Exception e)
        {
            log.error("Shutdown flush: failed to mirror obtained set to ConfigManager.", e);
        }
    }

    private void reconcileWithCloud(boolean runtime)
    {
        String player = accountManager.getPlayerName();
        if (player == null) return;

        Path newFile = safeGetFilePathOrNull(FILE_NAME);
        if (newFile == null) return;

        boolean newFileExisted = Files.exists(newFile);

        migrateLegacyLocalObtainedIfNeeded();

        // Re-check existence after migration attempt.
        newFileExisted = Files.exists(newFile);

        // Read local new first; if missing, seed from legacy rolled file (if it still exists)
        Path legacyFile = safeGetFilePathOrNull(LEGACY_FILE_NAME);
        boolean legacySeeded = false;

        Set<Integer> localNew = readLocalJson(newFile);
        Set<Integer> local;
        if (!localNew.isEmpty() || newFileExisted)
        {
            local = localNew;
        }
        else
        {
            Set<Integer> legacySet = (legacyFile != null) ? readLocalJson(legacyFile) : new LinkedHashSet<>();
            local = legacySet;
            legacySeeded = !legacySet.isEmpty();
        }

        long localMtime = newFileExisted ? safeLastModified(newFile) : 0L;

        // Cloud: new + legacy
        ConfigPersistence.StampedSet cloudStampedNew = readCloud(player, CFG_KEY);
        ConfigPersistence.StampedSet cloudStampedLegacy = readCloud(player, LEGACY_CFG_KEY);

        Set<Integer> cloudNew = new LinkedHashSet<>(cloudStampedNew.data);
        long cloudNewTs = cloudStampedNew.ts;

        Set<Integer> cloudLegacy = new LinkedHashSet<>(cloudStampedLegacy.data);
        long cloudLegacyTs = cloudStampedLegacy.ts;

        // If new cloud is empty, allow legacy to seed
        Set<Integer> cloudMerged = new LinkedHashSet<>(cloudNew);
        if (cloudMerged.isEmpty() && !cloudLegacy.isEmpty())
        {
            cloudMerged.addAll(cloudLegacy);
        }

        long cloudTs = Math.max(cloudNewTs, cloudLegacyTs);

        // LWW between local and (merged) cloud
        Set<Integer> winner;
        Long winnerStamp = null;
        boolean needPersist;

        if (localMtime > cloudTs) { winner = local; winnerStamp = localMtime; needPersist = true; }
        else if (cloudTs > localMtime) { winner = cloudMerged; winnerStamp = cloudTs; needPersist = true; }
        else { winner = local; needPersist = !newFileExisted; }

        synchronized (obtainedItems)
        {
            obtainedItems.clear();
            obtainedItems.addAll(winner);
        }
        if (legacySeeded && legacyFile != null && Files.exists(legacyFile) && !newFileExisted)
        {
            try
            {
                archiveLegacyFile(legacyFile);
            }
            catch (IOException ioe)
            {
                log.error("Failed to archive legacy rolled file during obtained migration", ioe);
            }
        }

        if (needPersist)
        {
            long stamp = (winnerStamp != null) ? winnerStamp : System.currentTimeMillis();
            saveInternal(stamp, false); // bypass debounce during reconcile
        }
        else if (!Files.exists(newFile) && isExecutorAvailable())
        {
            // Ensure file exists locally on fresh machines
            saveInternal(System.currentTimeMillis(), false);
        }

        dirty = false;
    }

    private void migrateLegacyLocalObtainedIfNeeded()
    {
        Path obtainedFile = safeGetFilePathOrNull(FILE_NAME);
        Path legacyObtained = safeGetFilePathOrNull(LEGACY_FILE_NAME);
        Path legacyUnlocked = safeGetFilePathOrNull(LEGACY_UNLOCKED_FILE);

        if (obtainedFile == null || legacyObtained == null || legacyUnlocked == null) return;

        if (Files.exists(obtainedFile)) return;
        if (!Files.exists(legacyUnlocked)) return;
        if (!Files.exists(legacyObtained)) return;

        try
        {
            Set<Integer> legacyData = readLocalJson(legacyObtained);
            if (legacyData.isEmpty())
            {
                return;
            }

            Files.createDirectories(obtainedFile.getParent());

            try
            {
                Files.move(legacyObtained, obtainedFile, StandardCopyOption.REPLACE_EXISTING);
            }
            catch (IOException moveFail)
            {
                Files.copy(legacyObtained, obtainedFile, StandardCopyOption.REPLACE_EXISTING);
                Files.deleteIfExists(legacyObtained);
            }

            log.info("ChanceMan v3 migration: moved legacy obtained file {} -> {}",
                    legacyObtained.getFileName(), obtainedFile.getFileName());
        }
        catch (Exception e)
        {
            log.error("ChanceMan v3 migration: failed to migrate legacy obtained file", e);
        }
    }

    /** Disk write + cloud mirror (debounced or immediate). */
    private void saveInternal(long stampMillis, boolean debounced)
    {
        if (!isExecutorAvailable())
        {
            log.error("ObtainedItemsManager: executor unavailable; skipping save");
            return;
        }

        executor.submit(() ->
        {
            Path file = safeGetFilePathOrNull(FILE_NAME);
            if (file == null)
            {
                log.error("ObtainedItemsManager: file path unavailable; skipping save");
                return;
            }
            try
            {
                rotateBackupIfExists(file);
                Set<Integer> snap = snapshotObtained();
                writeJsonAtomic(file, snap);
                mirrorToCloud(stampMillis, debounced, snap);
                dirty = false;
            }
            catch (IOException e)
            {
                log.error("Error saving obtained items", e);
            }
        });
    }

    /** Mirror to cloud, optionally debounced; uses provided snapshot to avoid re-locking. */
    private void mirrorToCloud(long stampMillis, boolean debounced, Set<Integer> snapshot)
    {
        long now = System.currentTimeMillis();
        if (debounced && (now - lastConfigWriteMs < CONFIG_DEBOUNCE_MS)) return;
        lastConfigWriteMs = now;

        String player = accountManager.getPlayerName();
        if (player == null || player.isEmpty() || executor == null) return;

        final Set<Integer> snap = (snapshot != null) ? snapshot : snapshotObtained();

        executor.submit(() ->
        {
            try
            {
                configPersistence.writeStampedSetIfNewer(player, CFG_KEY, snap, stampMillis);
            }
            catch (Exception e)
            {
                if (!configWriteWarned)
                {
                    configWriteWarned = true;
                    log.error("ChanceMan: failed to mirror obtained set to ConfigManager (local saves intact).", e);
                }
            }
        });
    }

    private boolean isExecutorAvailable()
    {
        if (executor == null) return false;
        if (executor instanceof java.util.concurrent.ThreadPoolExecutor)
        {
            java.util.concurrent.ThreadPoolExecutor tpe = (java.util.concurrent.ThreadPoolExecutor) executor;
            return !tpe.isShutdown() && !tpe.isTerminated();
        }
        return true;
    }

    private void safeNotifyChange()
    {
        Runnable cb = onChange;
        if (cb != null)
        {
            try { cb.run(); }
            catch (Throwable t) { log.error("onChange threw", t); }
        }
    }

    private Path getFilePath(String fileName) throws IOException
    {
        String name = accountManager.getPlayerName();
        if (name == null) throw new IOException("Player name is null");
        Path dir = RUNELITE_DIR.toPath().resolve("chanceman").resolve(name);
        Files.createDirectories(dir);
        return dir.resolve(fileName);
    }

    private Path safeGetFilePathOrNull(String fileName)
    {
        try { return getFilePath(fileName); }
        catch (IOException ioe) { return null; }
    }

    /** Move a legacy file out of the way so the new domain file name can take over. */
    private void archiveLegacyFile(Path legacyFile) throws IOException
    {
        Path backups = legacyFile.getParent().resolve("backups");
        Files.createDirectories(backups);

        String ts = new SimpleDateFormat(BACKUP_TS_PATTERN).format(new Date());
        Path archived = backups.resolve(legacyFile.getFileName() + ".migrated." + ts + ".bak");

        try
        {
            Files.move(legacyFile, archived, StandardCopyOption.REPLACE_EXISTING);
        }
        catch (IOException moveFail)
        {
            Files.copy(legacyFile, archived, StandardCopyOption.REPLACE_EXISTING);
            Files.deleteIfExists(legacyFile);
        }
    }

    /** Best effort copy of the current file to a timestamped backup, then prune. */
    private void rotateBackupIfExists(Path file) throws IOException
    {
        if (!Files.exists(file)) return;

        Path backups = file.getParent().resolve("backups");
        Files.createDirectories(backups);

        String ts = new SimpleDateFormat(BACKUP_TS_PATTERN).format(new Date());
        Path bak = backups.resolve(file.getFileName() + "." + ts + ".bak");

        try
        {
            Files.copy(file, bak, StandardCopyOption.REPLACE_EXISTING);
        }
        catch (FileSystemException fse)
        {
            log.warn("Backup copy failed for {}", file, fse);
        }

        try (java.util.stream.Stream<Path> stream = Files.list(backups))
        {
            stream
                    .filter(p -> p.getFileName().toString().startsWith(file.getFileName() + "."))
                    .sorted(Comparator.comparing(Path::getFileName).reversed())
                    .skip(MAX_BACKUPS)
                    .forEach(p -> { try { Files.deleteIfExists(p); } catch (IOException ignored) {} });
        }
    }

    /** Write JSON to .tmp and atomically replace the main file; mark self-write for watcher echo suppression. */
    private void writeJsonAtomic(Path file, Set<Integer> data) throws IOException
    {
        Path tmp = file.resolveSibling(file.getFileName() + ".tmp");
        try (BufferedWriter w = Files.newBufferedWriter(tmp)) { gson.toJson(data, w); }
        safeMove(tmp, file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
        lastSelfWriteMs = System.currentTimeMillis();
    }

    /** Move with fallback when ATOMIC_MOVE not supported. */
    private void safeMove(Path source, Path target, CopyOption... opts) throws IOException
    {
        try
        {
            Files.move(source, target, opts);
        }
        catch (AtomicMoveNotSupportedException | AccessDeniedException ex)
        {
            Set<CopyOption> fallback = new HashSet<>(Arrays.asList(opts));
            fallback.remove(StandardCopyOption.ATOMIC_MOVE);
            fallback.add(StandardCopyOption.REPLACE_EXISTING);
            Files.move(source, target, fallback.toArray(new CopyOption[0]));
        }
    }

    private long safeLastModified(Path file)
    {
        try { return Files.getLastModifiedTime(file).toMillis(); }
        catch (IOException e) { return 0L; }
    }

    private Set<Integer> readLocalJson(Path file)
    {
        Set<Integer> local = new LinkedHashSet<>();
        if (file == null) return local;

        try (Reader r = Files.newBufferedReader(file))
        {
            Set<Integer> loaded = gson.fromJson(r, SET_TYPE);
            if (loaded != null) local.addAll(loaded);
        }
        catch (NoSuchFileException ignored)
        {
            // Normal on fresh installs / multi-PC / atomic move race
            return local;
        }
        catch (IOException e)
        {
            log.error("Error reading obtained items JSON", e);
        }
        return local;
    }

    private ConfigPersistence.StampedSet readCloud(String player, String key)
    {
        try { return configPersistence.readStampedSet(player, key); }
        catch (Exception e) { return new ConfigPersistence.StampedSet(new LinkedHashSet<>(), 0L); }
    }

    private void closeWatchServiceQuietly()
    {
        try { if (watchService != null) watchService.close(); }
        catch (IOException ignored) {}
        watchService = null;
    }

    private void runWatcherLoop(String target)
    {
        long lastHandled = 0L;
        try
        {
            while (watcherRunning)
            {
                WatchKey key;
                try { key = watchService.take(); }
                catch (InterruptedException | ClosedWatchServiceException ie) { break; }

                boolean relevant = false;
                for (WatchEvent<?> ev : key.pollEvents())
                {
                    Object ctx = ev.context();
                    if (ctx instanceof Path && ((Path) ctx).getFileName().toString().equals(target))
                    {
                        relevant = true;
                    }
                }
                if (!key.reset()) break;
                if (!relevant) continue;

                long now = System.currentTimeMillis();
                if (now - lastSelfWriteMs <= SELF_WRITE_GRACE_MS) continue;
                if (now - lastHandled < FS_DEBOUNCE_MS) continue;
                lastHandled = now;

                try
                {
                    reconcileWithCloud(true);
                    safeNotifyChange();
                }
                catch (Throwable t)
                {
                    log.error("Obtained watcher reconcile failed", t);
                }
            }
        }
        finally
        {
            closeWatchServiceQuietly();
            watcherRunning = false;
        }
    }

    /** Take a consistent snapshot under the set's monitor. */
    private Set<Integer> snapshotObtained()
    {
        synchronized (obtainedItems)
        {
            return new LinkedHashSet<>(obtainedItems);
        }
    }
}

package com.chanceman.managers;

import com.chanceman.ChanceManOverlay;
import com.chanceman.ChanceManPanel;
import com.chanceman.ChanceManConfig;
import com.chanceman.rolls.RollPoolManager;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.ColorUtil;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.*;
import java.util.*;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;

/**
 * Manages roll animations and result announcements.
 *
 * New domain meanings:
 *  - ObtainedItemsManager = items you have obtained (legacy: Rolled)
 *  - RolledItemsManager   = items that have been rolled/unlocked (legacy: Unlocked)
 */
@Singleton
public class RollAnimationManager
{
    private static final int SNAP_WINDOW_MS = 350;
    @Inject private ItemManager itemManager;
    @Inject private Client client;
    @Inject private ClientThread clientThread;

    @Inject private RolledItemsManager rolledManager;
    @Inject private RollPoolManager rollPoolManager;

    @Inject private ChanceManOverlay overlay;
    @Inject private ChanceManConfig config;

    @Setter private ChanceManPanel chanceManPanel;

    private Set<Integer> allTradeableItems = Collections.emptySet();

    private final Queue<Integer> rollQueue = new ConcurrentLinkedQueue<>();
    private ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();

    @Getter
    private volatile boolean isRolling = false;

    // tradeables gating
    private volatile boolean tradeablesReady = false;

    private volatile List<Integer> activeRollPool = Collections.emptyList();

    @Getter
    @Setter
    private volatile boolean manualRoll = false;

    /** Called by plugin after building tradeables. */
    public void setAllTradeableItems(Set<Integer> allTradeableItems)
    {
        this.allTradeableItems = (allTradeableItems != null)
                ? Collections.unmodifiableSet(new LinkedHashSet<>(allTradeableItems))
                : Collections.emptySet();
        this.tradeablesReady = !this.allTradeableItems.isEmpty();
    }

    public boolean hasTradeablesReady()
    {
        return tradeablesReady && !allTradeableItems.isEmpty();
    }

    /**
     * Enqueue an obtained item that should trigger a roll.
     *
     * @param obtainedItemId item that caused the roll
     */
    public void enqueueRoll(int obtainedItemId)
    {
        rollQueue.offer(obtainedItemId);
    }

    /**
     * Process pending rolls if idle.
     */
    public void process()
    {
        if (!hasTradeablesReady() || isRolling)
        {
            return; // queue stays intact until tradeables are built
        }

        Integer obtainedItemId = rollQueue.poll();
        if (obtainedItemId == null)
        {
            return;
        }

        isRolling = true;
        executor.submit(() -> performRoll(obtainedItemId));
    }

    /**
     * Perform the roll animation and announce the result.
     * The rolled item is selected during the snap window and immediately
     * marked as ROLLED (legacy: unlocked), while the animation finishes visually.
     */
    private void performRoll(int obtainedItemId)
    {
        if (!hasTradeablesReady())
        {
            finishRoll();
            return;
        }

        boolean toolGuaranteeEnabled = config.enableToolRollGuarantee();
        boolean questItemRollsEnabled = config.enableQuestItemRolls();
        boolean wasManual = manualRoll;

        activeRollPool = rollPoolManager.selectPool(
                allTradeableItems,
                rolledManager.getRolledItems(),
                toolGuaranteeEnabled,
                questItemRollsEnabled
        );

        if (activeRollPool.isEmpty())
        {
            finishRoll();
            return;
        }

        int rollDuration = 3000;
        overlay.startRollAnimation(0, rollDuration, this::getRandomLockedItem);

        executor.schedule(
                () -> completeRoll(
                        obtainedItemId,
                        wasManual,
                        toolGuaranteeEnabled,
                        questItemRollsEnabled
                ),
                rollDuration + SNAP_WINDOW_MS,
                TimeUnit.MILLISECONDS
        );

        executor.schedule(
                this::finishRoll,
                rollDuration + overlay.getHighlightDurationMs(),
                TimeUnit.MILLISECONDS
        );
    }

    private void completeRoll(
            int obtainedItemId,
            boolean wasManual,
            boolean toolGuaranteeEnabled,
            boolean questItemRollsEnabled)
    {
        int rolledItemId = overlay.getFinalItem();
        if (rolledItemId <= 0 || rolledManager.isRolled(rolledItemId))
        {
            finishRoll();
            return;
        }

        rolledManager.markRolled(rolledItemId);
        rollPoolManager.recordCompletedRoll(
                rolledItemId,
                toolGuaranteeEnabled,
                questItemRollsEnabled
        );

        clientThread.invoke(() ->
        {
            String rolledTag = ColorUtil.wrapWithColorTag(
                    getItemName(rolledItemId),
                    config.unlockedItemColor()
            );

            String message;
            if (wasManual)
            {
                String pressTag = ColorUtil.wrapWithColorTag(
                        "pressing a button",
                        config.rolledItemColor()
                );
                message = "Rolled " + rolledTag + " by " + pressTag;
            }
            else
            {
                String obtainedTag = ColorUtil.wrapWithColorTag(
                        getItemName(obtainedItemId),
                        config.rolledItemColor()
                );
                message = "Rolled " + rolledTag + " by obtaining " + obtainedTag;
            }

            client.addChatMessage(
                    ChatMessageType.GAMEMESSAGE,
                    "",
                    message,
                    null
            );

            if (chanceManPanel != null)
            {
                SwingUtilities.invokeLater(chanceManPanel::updatePanel);
            }
        });
    }

    private void finishRoll()
    {
        activeRollPool = Collections.emptyList();
        manualRoll = false;
        isRolling = false;
    }

    /**
     * Pick a random locked item to display during the roll.
     */
    private int getRandomLockedItem()
    {
        List<Integer> pool = activeRollPool;
        if (pool.isEmpty())
        {
            return overlay.getFinalItem();
        }

        return pool.get(ThreadLocalRandom.current().nextInt(pool.size()));
    }

    private String getItemName(int itemId)
    {
        ItemComposition comp = itemManager.getItemComposition(itemId);
        return comp.getName();
    }

    public void startUp()
    {
        if (executor == null || executor.isShutdown() || executor.isTerminated())
        {
            executor = Executors.newSingleThreadScheduledExecutor();
        }
    }

    public void shutdown()
    {
        rollQueue.clear();
        activeRollPool = Collections.emptyList();
        manualRoll = false;
        isRolling = false;
        executor.shutdownNow();
    }
}

package com.chanceman.managers;

import com.chanceman.account.AccountManager;
import com.chanceman.persist.ConfigPersistence;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.Reader;
import java.lang.reflect.Type;
import java.nio.file.*;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.concurrent.ExecutorService;

import static net.runelite.client.RuneLite.RUNELITE_DIR;

@Slf4j
@Singleton
public class RolledItemsManager
{
    private static final int MAX_BACKUPS = 10;
    private static final String CFG_KEY = "unlocked";
    private static final String FILE_NAME = "chanceman_rolled.json";
    private static final String LEGACY_FILE_NAME = "chanceman_unlocked.json";

    private static final String BACKUP_TS_PATTERN = "yyyyMMddHHmmss";
    private static final long CONFIG_DEBOUNCE_MS = 3000L;
    private static final long SELF_WRITE_GRACE_MS = 1500L;
    private static final long FS_DEBOUNCE_MS = 200L;

    private static final Type SET_TYPE = new TypeToken<Set<Integer>>(){}.getType();
    private final Set<Integer> rolledItems = Collections.synchronizedSet(new LinkedHashSet<>());

    @Inject private AccountManager accountManager;
    @Inject private Gson gson;
    @Inject private ConfigPersistence configPersistence;

    @Setter private ExecutorService executor; // file writes & cloud mirror
    @Setter private Runnable onChange; // optional UI refresh

    private volatile long lastConfigWriteMs = 0L;
    private volatile boolean configWriteWarned = false;
    private volatile boolean dirty = false;

    private WatchService watchService;
    private volatile boolean watcherRunning = false;
    private volatile long lastSelfWriteMs = 0L;
    private Thread watcherThread;
    public boolean ready() { return accountManager.getPlayerName() != null; }

    public boolean isRolled(int itemId) { return rolledItems.contains(itemId); }

    /** Return an immutable snapshot to avoid leaking the synchronizedSet. */
    public Set<Integer> getRolledItems()
    {
        synchronized (rolledItems)
        {
            return Collections.unmodifiableSet(new LinkedHashSet<>(rolledItems));
        }
    }

    public void markRolled(int itemId)
    {
        if (rolledItems.add(itemId))
        {
            dirty = true;
            safeNotifyChange();
            saveRolledItems();
        }
    }

    /** Initial load + LWW reconciliation. */
    public void loadRolledItems()
    {
        reconcileWithCloud(false);
        safeNotifyChange();
    }

    /** Normal save: disk + debounced cloud with current time. */
    public void saveRolledItems()
    {
        saveInternal(System.currentTimeMillis(), true);
    }

    /** Start watching the JSON on a dedicated daemon thread. */
    public void startWatching()
    {
        if (watcherRunning) return;
        Path file = safeGetFilePathOrNull(FILE_NAME);
        if (file == null) return;

        try
        {
            watchService = FileSystems.getDefault().newWatchService();
            file.getParent().register(
                    watchService,
                    StandardWatchEventKinds.ENTRY_CREATE,
                    StandardWatchEventKinds.ENTRY_MODIFY,
                    StandardWatchEventKinds.ENTRY_DELETE
            );
        }
        catch (IOException e)
        {
            closeWatchServiceQuietly();
            log.error("Rolled watcher: could not register", e);
            return;
        }

        watcherRunning = true;
        final String target = file.getFileName().toString();
        watcherThread = new Thread(() -> runWatcherLoop(target), "ChanceMan-Rolled-Watcher");
        watcherThread.setDaemon(true);
        watcherThread.start();
    }

    /** Stop watching the JSON. */
    public void stopWatching()
    {
        watcherRunning = false;
        closeWatchServiceQuietly();
        watcherThread = null;
    }

    /** Flush synchronously on shutdown if dirty. */
    public void flushIfDirtyOnExit()
    {
        if (!dirty) return;
        Path file = safeGetFilePathOrNull(FILE_NAME);
        if (file == null) return;

        try
        {
            rotateBackupIfExists(file);
            Set<Integer> snap = snapshotRolled();
            writeJsonAtomic(file, snap);
            mirrorToCloud(System.currentTimeMillis(), false, snap);
            dirty = false;
        }
        catch (IOException e)
        {
            log.error("Shutdown flush failed for rolled items (local saves may be stale).", e);
        }
        catch (Exception e)
        {
            log.error("Shutdown flush: failed to mirror rolled set to ConfigManager.", e);
        }
    }

    private void reconcileWithCloud(boolean runtime)
    {
        String player = accountManager.getPlayerName();
        if (player == null) return;
        migrateLegacyLocalRolledIfNeeded();
        Path newFile = safeGetFilePathOrNull(FILE_NAME);
        if (newFile == null) return;

        boolean newFileExisted = Files.exists(newFile);

        // Read local new first; if missing, seed from legacy unlocked file
        Path legacyFile = safeGetFilePathOrNull(LEGACY_FILE_NAME);

        Set<Integer> localNew = readLocalJson(newFile);
        Set<Integer> local;
        if (!localNew.isEmpty() || newFileExisted)
        {
            local = localNew;
        }
        else
        {
            local = (legacyFile != null) ? readLocalJson(legacyFile) : new LinkedHashSet<>();
        }

        long localMtime = newFileExisted ? safeLastModified(newFile) : 0L;

        // Cloud
        ConfigPersistence.StampedSet cloudStamped = readCloud(player, CFG_KEY);
        Set<Integer> cloud = new LinkedHashSet<>(cloudStamped.data);
        long cloudTs = cloudStamped.ts;

        // LWW between local and cloud
        Set<Integer> winner;
        Long winnerStamp = null;
        boolean needPersist;

        if (localMtime > cloudTs) { winner = local; winnerStamp = localMtime; needPersist = true; }
        else if (cloudTs > localMtime) { winner = cloud; winnerStamp = cloudTs; needPersist = true; }
        else { winner = local; needPersist = !newFileExisted; }

        synchronized (rolledItems)
        {
            rolledItems.clear();
            rolledItems.addAll(winner);
        }

        if (needPersist)
        {
            long stamp = (winnerStamp != null) ? winnerStamp : System.currentTimeMillis();
            saveInternal(stamp, false); // bypass debounce during reconcile
        }
        else if (!Files.exists(newFile) && isExecutorAvailable())
        {
            // Ensure file exists locally on fresh machines
            saveInternal(System.currentTimeMillis(), false);
        }

        dirty = false;
    }

    private void migrateLegacyLocalRolledIfNeeded()
    {
        Path rolledFile = safeGetFilePathOrNull(FILE_NAME); // chanceman_rolled.json (new rolled)
        Path legacyUnlocked = safeGetFilePathOrNull(LEGACY_FILE_NAME); // chanceman_unlocked.json (legacy rolled)
        if (rolledFile == null || legacyUnlocked == null) return;
        if (Files.exists(rolledFile)) return;
        if (!Files.exists(legacyUnlocked)) return;

        try
        {
            Set<Integer> legacyData = readLocalJson(legacyUnlocked);
            if (legacyData.isEmpty()) return;

            Files.createDirectories(rolledFile.getParent());

            Files.copy(legacyUnlocked, rolledFile, StandardCopyOption.REPLACE_EXISTING);

            log.info("ChanceMan v3 migration: copied legacy rolled file {} -> {}",
                    legacyUnlocked.getFileName(), rolledFile.getFileName());
        }
        catch (Exception e)
        {
            log.error("ChanceMan v3 migration: failed to migrate legacy rolled file unlocked.json -> rolled.json", e);
        }
    }

    /** Disk write + cloud mirror (debounced or immediate). */
    private void saveInternal(long stampMillis, boolean debounced)
    {
        if (!isExecutorAvailable())
        {
            log.error("RolledItemsManager: executor unavailable; skipping save");
            return;
        }

        executor.submit(() ->
        {
            Path file = safeGetFilePathOrNull(FILE_NAME);
            if (file == null)
            {
                log.error("RolledItemsManager: file path unavailable; skipping save");
                return;
            }
            try
            {
                rotateBackupIfExists(file);
                Set<Integer> snap = snapshotRolled();
                writeJsonAtomic(file, snap);
                mirrorToCloud(stampMillis, debounced, snap);
                dirty = false;
            }
            catch (IOException e)
            {
                log.error("Error saving rolled items", e);
            }
        });
    }

    /** Mirror to cloud, optionally debounced; uses provided snapshot to avoid re-locking. */
    private void mirrorToCloud(long stampMillis, boolean debounced, Set<Integer> snapshot)
    {
        long now = System.currentTimeMillis();
        if (debounced && (now - lastConfigWriteMs < CONFIG_DEBOUNCE_MS)) return;
        lastConfigWriteMs = now;

        String player = accountManager.getPlayerName();
        if (player == null || player.isEmpty() || executor == null) return;

        final Set<Integer> snap = (snapshot != null) ? snapshot : snapshotRolled();

        executor.submit(() ->
        {
            try
            {
                configPersistence.writeStampedSetIfNewer(player, CFG_KEY, snap, stampMillis);
            }
            catch (Exception e)
            {
                if (!configWriteWarned)
                {
                    configWriteWarned = true;
                    log.error("ChanceMan: failed to mirror rolled set to ConfigManager (local saves intact).", e);
                }
            }
        });
    }

    private boolean isExecutorAvailable()
    {
        if (executor == null) return false;
        if (executor instanceof java.util.concurrent.ThreadPoolExecutor)
        {
            java.util.concurrent.ThreadPoolExecutor tpe = (java.util.concurrent.ThreadPoolExecutor) executor;
            return !tpe.isShutdown() && !tpe.isTerminated();
        }
        return true;
    }

    private void safeNotifyChange()
    {
        Runnable cb = onChange;
        if (cb != null)
        {
            try { cb.run(); }
            catch (Throwable t) { log.error("onChange threw", t); }
        }
    }

    private Path getFilePath(String fileName) throws IOException
    {
        String name = accountManager.getPlayerName();
        if (name == null) throw new IOException("Player name is null");
        Path dir = RUNELITE_DIR.toPath().resolve("chanceman").resolve(name);
        Files.createDirectories(dir);
        return dir.resolve(fileName);
    }

    private Path safeGetFilePathOrNull(String fileName)
    {
        try { return getFilePath(fileName); }
        catch (IOException ioe) { return null; }
    }

    /** Best effort copy of the current file to a timestamped backup, then prune. */
    private void rotateBackupIfExists(Path file) throws IOException
    {
        if (!Files.exists(file)) return;

        Path backups = file.getParent().resolve("backups");
        Files.createDirectories(backups);

        String ts = new SimpleDateFormat(BACKUP_TS_PATTERN).format(new Date());
        Path bak = backups.resolve(file.getFileName() + "." + ts + ".bak");

        try
        {
            Files.copy(file, bak, StandardCopyOption.REPLACE_EXISTING);
        }
        catch (FileSystemException fse)
        {
            log.warn("Backup copy failed for {}", file, fse);
        }

        try (java.util.stream.Stream<Path> stream = Files.list(backups))
        {
            stream
                    .filter(p -> p.getFileName().toString().startsWith(file.getFileName() + "."))
                    .sorted(Comparator.comparing(Path::getFileName).reversed())
                    .skip(MAX_BACKUPS)
                    .forEach(p -> { try { Files.deleteIfExists(p); } catch (IOException ignored) {} });
        }
    }

    /** Write JSON to .tmp and atomically replace the main file; mark self-write for watcher echo suppression. */
    private void writeJsonAtomic(Path file, Set<Integer> data) throws IOException
    {
        Path tmp = file.resolveSibling(file.getFileName() + ".tmp");
        try (BufferedWriter w = Files.newBufferedWriter(tmp)) { gson.toJson(data, w); }
        safeMove(tmp, file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
        lastSelfWriteMs = System.currentTimeMillis();
    }

    /** Move with fallback when ATOMIC_MOVE not supported. */
    private void safeMove(Path source, Path target, CopyOption... opts) throws IOException
    {
        try { Files.move(source, target, opts); }
        catch (AtomicMoveNotSupportedException | AccessDeniedException ex)
        {
            Set<CopyOption> fallback = new HashSet<>(Arrays.asList(opts));
            fallback.remove(StandardCopyOption.ATOMIC_MOVE);
            fallback.add(StandardCopyOption.REPLACE_EXISTING);
            Files.move(source, target, fallback.toArray(new CopyOption[0]));
        }
    }

    private long safeLastModified(Path file)
    {
        try { return Files.getLastModifiedTime(file).toMillis(); }
        catch (IOException e) { return 0L; }
    }

    private Set<Integer> readLocalJson(Path file)
    {
        Set<Integer> local = new LinkedHashSet<>();
        if (file == null) return local;

        try (Reader r = Files.newBufferedReader(file))
        {
            Set<Integer> loaded = gson.fromJson(r, SET_TYPE);
            if (loaded != null) local.addAll(loaded);
        }
        catch (NoSuchFileException ignored)
        {
            return local;
        }
        catch (IOException e)
        {
            log.error("Error reading rolled items JSON", e);
        }
        return local;
    }

    private ConfigPersistence.StampedSet readCloud(String player, String key)
    {
        try { return configPersistence.readStampedSet(player, key); }
        catch (Exception e) { return new ConfigPersistence.StampedSet(new LinkedHashSet<>(), 0L); }
    }

    private void closeWatchServiceQuietly()
    {
        try { if (watchService != null) watchService.close(); }
        catch (IOException ignored) {}
        watchService = null;
    }

    private void runWatcherLoop(String target)
    {
        long lastHandled = 0L;
        try
        {
            while (watcherRunning)
            {
                WatchKey key;
                try { key = watchService.take(); }
                catch (InterruptedException | ClosedWatchServiceException ie) { break; }

                boolean relevant = false;
                for (WatchEvent<?> ev : key.pollEvents())
                {
                    Object ctx = ev.context();
                    if (ctx instanceof Path && ((Path) ctx).getFileName().toString().equals(target))
                    {
                        relevant = true;
                    }
                }
                if (!key.reset()) break;
                if (!relevant) continue;

                long now = System.currentTimeMillis();
                if (now - lastSelfWriteMs <= SELF_WRITE_GRACE_MS) continue;
                if (now - lastHandled < FS_DEBOUNCE_MS) continue;
                lastHandled = now;

                try
                {
                    reconcileWithCloud(true);
                    safeNotifyChange();
                }
                catch (Throwable t)
                {
                    log.error("Rolled watcher reconcile failed", t);
                }
            }
        }
        finally
        {
            closeWatchServiceQuietly();
            watcherRunning = false;
        }
    }

    /** Take a consistent snapshot under the set's monitor. */
    private Set<Integer> snapshotRolled()
    {
        synchronized (rolledItems)
        {
            return new LinkedHashSet<>(rolledItems);
        }
    }
}

package com.chanceman.menus;

import com.chanceman.ChanceManConfig;
import com.chanceman.ChanceManPlugin;
import com.chanceman.filters.EnsouledHeadMapping;
import com.chanceman.managers.RolledItemsManager;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;
import net.runelite.api.widgets.Widget;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.EnumSet;
import java.util.Set;
import java.util.function.Consumer;

@Singleton
public class ActionHandler {

    private static final Set<MenuAction> disabledActions = EnumSet.of(
            MenuAction.CC_OP,               // inventory “Use” on locked
            MenuAction.WIDGET_TARGET,       // “Use” on widgets
            MenuAction.WIDGET_TARGET_ON_WIDGET  // “Use” on widget -> widget
    );

    private static final Set<MenuAction> GROUND_ACTIONS = EnumSet.of(
            MenuAction.GROUND_ITEM_FIRST_OPTION,
            MenuAction.GROUND_ITEM_SECOND_OPTION,
            MenuAction.GROUND_ITEM_THIRD_OPTION,
            MenuAction.GROUND_ITEM_FOURTH_OPTION,
            MenuAction.GROUND_ITEM_FIFTH_OPTION
    );

    private static final Set<Integer> ALWAYS_ALLOW_OBJECT_IDS = Set.of(ObjectID.CATABOW);

    private static final EnumSet<MenuAction> GAME_OBJECT_ACTIONS = EnumSet.of(
            MenuAction.GAME_OBJECT_FIRST_OPTION,
            MenuAction.GAME_OBJECT_SECOND_OPTION,
            MenuAction.GAME_OBJECT_THIRD_OPTION,
            MenuAction.GAME_OBJECT_FOURTH_OPTION,
            MenuAction.GAME_OBJECT_FIFTH_OPTION
    );

    private static final int ORBS_GROUP = (InterfaceID.Orbs.UNIVERSE >>> 16);
    // A no-op click handler that marks a menu entry as disabled.
    private final Consumer<MenuEntry> DISABLED = e -> {
    };
    @Inject
    private Client client;
    @Inject
    private EventBus eventBus;
    @Inject
    private ChanceManConfig config;
    @Inject
    private ChanceManPlugin plugin;
    @Inject
    private Restrictions restrictions;
    @Inject
    private RolledItemsManager rolledItemsManager;

    /**
     * A static helper to further safeguard ground item actions.
     * If a ground item is locked, this method consumes the event.
     */
    public static void handleGroundItems(
            ItemManager itemManager,
            RolledItemsManager rolledItemsManager,
            MenuOptionClicked event,
            ChanceManPlugin plugin) {
        if (event.getMenuAction() != null && GROUND_ACTIONS.contains(event.getMenuAction())) {
            int rawItemId = event.getId() != -1
                    ? event.getId()
                    : event.getMenuEntry().getItemId();
            int mapped = EnsouledHeadMapping.toTradeableId(rawItemId);
            int canonicalGroundId = itemManager.canonicalize(mapped);

            if (plugin.isInPlay(canonicalGroundId)
                    && rolledItemsManager != null
                    && !rolledItemsManager.isRolled(canonicalGroundId))
                event.consume();
        }
    }

    private EnabledUI getEnabledUI(MenuEntry entry) {
        Widget widget = entry.getWidget();
        if (widget == null) return null;

        int groupId = widget.getId() >>> 16;
        if (groupId == InterfaceID.BANKSIDE) return EnabledUI.BANK;
        return EnabledUI.fromGroupId(groupId);
    }

    /**
     * Normalize a MenuEntryAdded into the base item ID.
     */
    private int getItemId(MenuEntryAdded event, MenuEntry entry) {
        MenuAction type = entry.getType();
        boolean hasItemId = entry.getItemId() > 0 || event.getItemId() > 0;
        if (!GROUND_ACTIONS.contains(type) && !hasItemId) {
            return -1;
        }

        int raw = GROUND_ACTIONS.contains(type)
                ? event.getIdentifier()
                : Math.max(event.getItemId(), entry.getItemId());
        int mapped = EnsouledHeadMapping.toTradeableId(raw);
        return plugin.getItemManager().canonicalize(mapped);
    }

    public void startUp() {
        eventBus.register(this);
        eventBus.register(restrictions);
    }

    public void shutDown() {
        eventBus.unregister(this);
        eventBus.unregister(restrictions);
    }

    private boolean inactive() {
        return !rolledItemsManager.ready()
                || client.getGameState().getState() < GameState.LOADING.getState();
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event) {
        if (inactive()) return;

        MenuEntry entry = event.getMenuEntry();
        EnabledUI ui = getEnabledUI(entry);
        if (ui != null && (ui.isAllowAllActions() || !ui.isGreyLockedItems())) return;

        MenuAction action = entry.getType();
        int id = getItemId(event, entry);
        boolean enabled = GROUND_ACTIONS.contains(action)
                ? !isLockedGroundItem(id)
                : isEnabled(id, entry, action, ui);

        // If not enabled, grey out the text and set the click handler to DISABLED.
        if (!enabled) {
            String option = Text.removeTags(entry.getOption());
            String target = Text.removeTags(entry.getTarget());
            entry.setOption("<col=808080>" + option);
            entry.setTarget("<col=808080>" + target);
            entry.onClick(DISABLED);
            if (config.deprioritizeLockedOptions())
                entry.setDeprioritized(true);
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event) {
        // If the entry is disabled, consume the event.
        if (event.getMenuEntry().onClick() == DISABLED) {
            event.consume();
            return;
        }

        // Extra safeguard for ground items.
        handleGroundItems(plugin.getItemManager(), rolledItemsManager, event, plugin);
    }

    /**
     * @param itemId canonicalized item ID of a ground item
     * @return true if it is in play and still locked
     */
    private boolean isLockedGroundItem(int itemId) {
        return plugin.isInPlay(itemId)
                && !rolledItemsManager.isRolled(itemId);
    }

    private boolean isHealthOrbCure(MenuEntry entry) {
        if (entry.getType() != MenuAction.CC_OP
                || !"cure".equalsIgnoreCase(Text.removeTags(entry.getOption())))
            return false;

        int w1 = entry.getParam1();
        int w0 = entry.getParam0();
        return (w1 >>> 16) == ORBS_GROUP || (w0 >>> 16) == ORBS_GROUP;
    }

    private boolean hasLockedShantayPass() {
        if (rolledItemsManager.isRolled(ItemID.SHANTAY_PASS)) return false;

        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        if (inventory != null) {
            for (Item item : inventory.getItems())
                if (item.getId() == ItemID.SHANTAY_PASS) return true;
        }

        return false;
    }

    private boolean isShantayPassGateEntry(MenuEntry entry, String option) {
        if (!option.equalsIgnoreCase("go-through") || client.getLocalPlayer() == null)
            return false;

        int objectId = entry.getIdentifier();
        if (objectId != ObjectID.SHANTAY_PASS_HENGE_DOORWAY
                && objectId != ObjectID.TEMPOROSS_LOBBY_PASS)
            return false;

        WorldView worldView = client.getWorldView(entry.getWorldViewId());
        if (worldView == null) return false;

        WorldPoint player = client.getLocalPlayer().getWorldLocation();
        WorldPoint gate = WorldPoint.fromScene(
                worldView,
                entry.getParam0(),
                entry.getParam1(),
                worldView.getPlane()
        );

        if (objectId == ObjectID.SHANTAY_PASS_HENGE_DOORWAY)
            return player.getY() > gate.getY();

        return gate.getY() > 2830
                ? player.getX() <= 3193
                : player.getY() >= 2819;
    }

    /**
     * This method handles non-ground items (or any other cases) by checking if the item is enabled.
     * It returns true if the action should be allowed.
     */
    private boolean isEnabled(int id, MenuEntry entry, MenuAction action, EnabledUI ui) {
        if (isHealthOrbCure(entry)) return true;

        String option = Text.removeTags(entry.getOption());
        String target = Text.removeTags(entry.getTarget());

        if (ui != null && ui.isAllowAllActions()) return true;

        // Allowlisted world objects bypass all restrictions
        if (GAME_OBJECT_ACTIONS.contains(action)
                && ALWAYS_ALLOW_OBJECT_IDS.contains(entry.getIdentifier()))
            return true;

        if ((isShantayPassGateEntry(entry, option)
                || (target.equalsIgnoreCase("Shantay Guard")
                && (option.equalsIgnoreCase("talk-to") || option.equalsIgnoreCase("pass"))))
                && hasLockedShantayPass())
            return false;

        // Always allow "Drop" / "Check"
        if (option.equalsIgnoreCase("drop") || option.equalsIgnoreCase("check"))
            return true;

        if (option.equalsIgnoreCase("clean") || option.equalsIgnoreCase("rub"))
            return !plugin.isInPlay(id) || rolledItemsManager.isRolled(id);

        if ("harpoon".equalsIgnoreCase(option)
                && !hasAnyHarpoonInInvOrWorn()) {
            String t = target.toLowerCase();
            if (t.contains("fishing spot") || t.contains("spirit pool"))
                return true;
        }

        if (target.equalsIgnoreCase("Reward pool")
                && (option.equalsIgnoreCase("net") || option.equalsIgnoreCase("big-search")))
            return restrictions.isAnyNetEnabled();

        if (option.equalsIgnoreCase("net")
                && target.toLowerCase().contains("fishing spot"))
            return isNetFishingEnabled(entry);

        if (SkillOp.isSkillOp(option))
            return restrictions.isSkillOpEnabled(option);

        if (Spell.isSpell(option))
            return restrictions.isSpellOpEnabled(option);

        if (Spell.isSpell(target))
            return restrictions.isSpellOpEnabled(target);

        if (!disabledActions.contains(action)
                || id == 0
                || id == -1
                || !plugin.isInPlay(id))
            return true;

        return rolledItemsManager.isRolled(id);
    }

    private boolean isNetFishingEnabled(MenuEntry entry) {
        NPC npc = entry.getNpc();
        if (npc != null) {
            NPCComposition composition = npc.getTransformedComposition();
            if (composition == null) composition = npc.getComposition();

            String[] actions = composition.getActions();
            if (actions != null) {
                for (String npcAction : actions)
                    if ("Harpoon".equalsIgnoreCase(npcAction))
                        return restrictions.isSkillOpEnabled(SkillOp.BIG_NET.getOption());
            }
        }

        return restrictions.isSkillOpEnabled(SkillOp.SMALL_NET.getOption());
    }

    /**
     * Checks for harpoon in inventory and worn items for
     * barbarian fishing.
     **/
    private boolean hasAnyHarpoonInInvOrWorn() {
        return hasHarpoon(client.getItemContainer(InventoryID.WORN))
                || hasHarpoon(client.getItemContainer(InventoryID.INV));
    }

    private boolean hasHarpoon(ItemContainer container) {
        if (container != null) {
            for (Item item : container.getItems()) {
                SkillItem skillItem = SkillItem.fromId(item.getId());
                if (skillItem != null && skillItem.getSkillOp() == SkillOp.HARPOON)
                    return true;
            }
        }

        return false;
    }
}

package com.chanceman.menus;

import lombok.Getter;
import net.runelite.api.gameval.ItemID;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

@Getter
public enum BlightedSack
{
    ENTANGLE(
            ItemID.BLIGHTED_SACK_ENTANGLE,
            Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
                    "Snare", "Entangle", "Bind"
            )))
    ),
    SURGE(
            ItemID.BLIGHTED_SACK_SURGE,
            Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
                    "Wind Surge", "Water Surge", "Earth Surge", "Fire Surge",
                    "Wind Wave",  "Water Wave",  "Earth Wave",  "Fire Wave"
            )))
    ),
    TELEBLOCK(
            ItemID.BLIGHTED_SACK_TELEBLOCK,
            Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
                    "Tele Block", "Teleport to Target"
            )))
    ),
    VENGEANCE(
            ItemID.BLIGHTED_SACK_VENGEANCE,
            Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
                    "Vengeance", "Vengeance Other"
            )))
    ),
    ANCIENT_ICE(
            ItemID.BLIGHTED_SACK_ICEBARRAGE,
            Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
                    "Ice Rush", "Ice Burst", "Ice Blitz", "Ice Barrage"
            )))
    );

    private final int sackItemId;
    private final Set<String> allowedSpells;
    private static final Map<String, BlightedSack> SPELL_TO_SACK;
    static
    {
        Map<String, BlightedSack> map = new HashMap<>();
        for (BlightedSack sack : values())
        {
            for (String spell : sack.allowedSpells)
            {
                map.put(spell, sack);
            }
        }
        SPELL_TO_SACK = Collections.unmodifiableMap(map);
    }

    BlightedSack(int sackItemId, Set<String> allowedSpells)
    {
        this.sackItemId = sackItemId;
        this.allowedSpells = allowedSpells;
    }

    /**
     * @return the BlightedSack that grants this spell, or null if none.
     */
    public static BlightedSack fromSpell(String spellName)
    {
        return SPELL_TO_SACK.get(spellName);
    }
}

package com.chanceman.menus;

import lombok.Getter;
import net.runelite.api.gameval.InterfaceID;

@Getter
public enum EnabledUI
{
	BANK(InterfaceID.BANKMAIN, true, true),
	DEPOSIT_BOX(InterfaceID.BANK_DEPOSITBOX, true, true),
	CUSTOM_FUR_STORE(InterfaceID.HuntingCustomfurs.CONTENT, false, true),
	Crafting_Gold(InterfaceID.CraftingGold.UNIVERSE, false, true),
	TTREK_REWARDS(InterfaceID.TREK_REWARDS,false, true),
	SKILLMULTI(InterfaceID.Skillmulti.ALL, false, true),
	RUNEDOKU(InterfaceID.ROGUETRADER_SUDOKU, false, true),
	MTA_SHOP(InterfaceID.MAGICTRAINING_SHOP,false, true),
	GUARDIANS_OF_THE_RIFT(InterfaceID.GOTR_HUD, false, true);

	private final int id; // group id
	private final boolean greyLockedItems; // should grey/disable locked items in this UI
	private final boolean allowAllActions; // should bypass action restrictions in this UI

	EnabledUI(int id, boolean greyLockedItems, boolean allowAllActions)
	{
		this.id = (id > 0xFFFF) ? (id >>> 16) : id;
		this.greyLockedItems = greyLockedItems;
		this.allowAllActions = allowAllActions;
	}

	public static EnabledUI fromGroupId(int groupId)
	{
		for (EnabledUI ui : values())
		{
			if (ui.id == groupId) return ui;
		}
		return null;
	}
}

package com.chanceman.menus;

import com.chanceman.ChanceManPlugin;
import com.chanceman.managers.RolledItemsManager;
import com.chanceman.account.AccountManager;
import net.runelite.api.*;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.events.GameTick;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;

@Singleton
public class Restrictions
{
	private static final int[] RUNE_POUCH_TYPE_VARBITS = {
			29,    // RUNE_POUCH_RUNE1
			1622,  // RUNE_POUCH_RUNE2
			1623,  // RUNE_POUCH_RUNE3
			14285, // RUNE_POUCH_RUNE4
			15373, // RUNE_POUCH_RUNE5
			15374  // RUNE_POUCH_RUNE6
	};

	private static final int[] RUNE_POUCH_AMOUNT_VARBITS = {
			1624,  // RUNE_POUCH_AMOUNT1
			1625,  // RUNE_POUCH_AMOUNT2
			1626,  // RUNE_POUCH_AMOUNT3
			14286, // RUNE_POUCH_AMOUNT4
			15375, // RUNE_POUCH_AMOUNT5
			15376  // RUNE_POUCH_AMOUNT6
	};

	private static final WorldArea FOUNTAIN_OF_RUNE_AREA =
			new WorldArea(3367, 3890, 13, 9, 0);

	private boolean isInFountainArea()
	{
		WorldPoint lp = client.getLocalPlayer().getWorldLocation();
		return FOUNTAIN_OF_RUNE_AREA.contains(lp);
	}

	private boolean isInLMS()
	{
		EnumSet<WorldType> worldTypes = client.getWorldType();
		return (worldTypes.contains(WorldType.LAST_MAN_STANDING));

	}

	public static final int SPELL_REQUIREMENT_OVERLAY_NORMAL = InterfaceID.MagicSpellbook.TOOLTIP;
	public static final int AUTOCAST_REQUIREMENT_OVERLAY_NORMAL = InterfaceID.Autocast.INFO;

	@Inject private ChanceManPlugin plugin;
	@Inject private Client client;
	@Inject private RolledItemsManager rolledItemsManager;
	@Inject private AccountManager accountManager;
	private final Set<SkillOp> enabledSkillOps = EnumSet.noneOf(SkillOp.class);
	private final HashSet<Integer> availableRunes = new HashSet<>();

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!accountManager.ready()) return;
		enabledSkillOps.clear();
		availableRunes.clear();

		ItemContainer equippedItems = client.getItemContainer(InventoryID.WORN);
		ItemContainer inventoryItems = client.getItemContainer(InventoryID.INV);

		if (equippedItems != null)
		{
			Arrays.stream(equippedItems.getItems()).forEach(item -> {
				int id = item.getId();
				SkillItem skillItem = SkillItem.fromId(id);
				if (skillItem != null && !skillItem.isRequiresUnlock())
				{
					enabledSkillOps.add(skillItem.getSkillOp());
					return;
				}

				if (shouldSkipItem(id)) return;
				if (RuneProvider.isEquippedProvider(id))
					availableRunes.addAll(RuneProvider.getProvidedRunes(id));
				if (skillItem != null) enabledSkillOps.add(skillItem.getSkillOp());
			});
		}

		if (inventoryItems != null)
		{
			Arrays.stream(inventoryItems.getItems()).forEach(item -> {
				int id = item.getId();
				SkillItem skillItem = SkillItem.fromId(id);
				if (skillItem != null && !skillItem.isRequiresUnlock())
				{
					enabledSkillOps.add(skillItem.getSkillOp());
					return;
				}

				if (shouldSkipItem(id)) return;
				if (RuneProvider.isInvProvider(id))
					availableRunes.addAll(RuneProvider.getProvidedRunes(id));
				if (skillItem != null) enabledSkillOps.add(skillItem.getSkillOp());
			});
		}

		EnumComposition pouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		for (int i = 0; i < 6; i++)
		{
			int qty     = client.getVarbitValue(RUNE_POUCH_AMOUNT_VARBITS[i]);
			int typeIdx = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[i]);
			if (qty <= 0)
			{
				continue;
			}

			int runeId = pouchEnum.getIntValue(typeIdx);
			if (shouldSkipItem(runeId))
			{
				continue;
			}

			if (RuneProvider.isInvProvider(runeId))
			{
				availableRunes.addAll(RuneProvider.getProvidedRunes(runeId));
			}
		}
	}

	public boolean isSkillOpEnabled(String option)
	{
		SkillOp op = SkillOp.fromString(option);
		return enabledSkillOps.contains(op);
	}

	public boolean isAnyNetEnabled()
	{
		return enabledSkillOps.contains(SkillOp.SMALL_NET)
				|| enabledSkillOps.contains(SkillOp.BIG_NET);
	}

	private boolean shouldSkipItem(int id)
	{
		if (!plugin.isInPlay(id))
		{
			return !(RuneProvider.isEquippedProvider(id)
					|| RuneProvider.isInvProvider(id));
		}
		return !rolledItemsManager.isRolled(id);
	}

	public boolean isSpellOpEnabled(String spellName)
	{
		if (isInFountainArea() || isInLMS()) { return true; }
		BlightedSack sack = BlightedSack.fromSpell(spellName);
		if (sack != null)
		{
			int sackId = sack.getSackItemId();
			ItemContainer inv = client.getItemContainer(InventoryID.INV);
			if (inv != null	&& (sackId == ItemID.BLIGHTED_SACK_SURGE || rolledItemsManager.isRolled(sackId)))
			{
				for (Item item : inv.getItems())
				{
					if (item.getId() == sackId)
					{
						return true;
					}
				}
			}
		}

		Widget autocastOverlay = client.getWidget(AUTOCAST_REQUIREMENT_OVERLAY_NORMAL);
		if (autocastOverlay != null) return processChildren(autocastOverlay);

		Widget spellOverlay = client.getWidget(SPELL_REQUIREMENT_OVERLAY_NORMAL);
		if (spellOverlay != null) return processChildren(spellOverlay);
		return false;
	}

	public boolean processChildren(Widget widget)
	{
		Widget[] children = widget.getDynamicChildren();
		if (children == null) return true;

		for (Widget child : children)
		{
			int id = child.getItemId();
			if (id == -1) continue;

			if (plugin.isInPlay(id) && !availableRunes.contains(id))
				return false;
		}
		return true;
	}
}

