import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.PluginInstantiationException;
import net.runelite.client.plugins.PluginManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import java.awt.Polygon;

@Singleton
public class TutorialIslandGuard {
    private static final Polygon TUTORIAL_ISLAND_POLY = new Polygon(
            new int[]{3111, 3112, 3116, 3122, 3125, 3131, 3135, 3145, 3153, 3150, 3148, 3150, 3146, 3141, 3142, 3134, 3121, 3108, 3099, 3091, 3070, 3071, 3065, 3065, 3065, 3057, 3056, 3067, 3064, 3064, 3065, 3069, 3072, 3077, 3081, 3087, 3096, 3101, 3108, 3110, 3111},
            new int[]{3054, 3060, 3062, 3066, 3069, 3070, 3073, 3074, 3077, 3092, 3100, 3103, 3114, 3123, 3128, 3133, 3133, 3130, 3131, 3133, 3133, 3125, 3119, 3111, 3104, 3100, 3094, 3082, 3075, 3067, 3063, 3063, 3066, 3065, 3061, 3058, 3064, 3068, 3065, 3062, 3062},
            41
    );

    private static final String CFG_GROUP = "chanceman";
    private static final String CFG_TUT_DONE = "tutIslandDone";

    @Inject
    private ConfigManager configManager;

    @Inject
    private Client client;
    @Inject
    private EventBus eventBus;

    @Inject
    private PluginManager pluginManager;
    @Inject
    private ChanceManPlugin plugin;

    private boolean shown = false;

    private static String keyForAccountHash(long accountHash) {
        return CFG_TUT_DONE + ".hash." + accountHash;
    }

    public void startUp() {
        shown = false;
        eventBus.register(this);
    }

    public void shutDown() {
        eventBus.unregister(this);
        shown = false;
    }

    private String currentPlayerKey() {
        long accountHash = client.getAccountHash();
        if (accountHash == -1) {
            return null;
        }

        return keyForAccountHash(accountHash);
    }

    private boolean isTutDone() {
        String key = currentPlayerKey();
        if (key == null) {
            return false;
        }
        Boolean v = configManager.getConfiguration(CFG_GROUP, key, Boolean.class);
        return Boolean.TRUE.equals(v);
    }

    private void setTutDone() {
        String key = currentPlayerKey();
        if (key == null) {
            return;
        }
        configManager.setConfiguration(CFG_GROUP, key, true);
    }

    @Subscribe
    public void onGameTick(GameTick e) {
        if (isTutDone()) {
            return;
        }

        Player p = client.getLocalPlayer();
        if (p == null) {
            return;
        }

        WorldPoint wp = p.getWorldLocation();

        if (wp.getPlane() != 0) {
            return;
        }

        // Automatically mark complete as soon as the player is outside Tutorial Island.
        if (!TUTORIAL_ISLAND_POLY.contains(wp.getX(), wp.getY())) {
            setTutDone();
            return;
        }

        if (shown) {
            return;
        }
        shown = true;

        SwingUtilities.invokeLater(() ->
        {
            JOptionPane.showMessageDialog(
                    null,
                    "Please leave Chance Man off until AFTER you leave tut island and SELL ALL your tut island stuff!"
                            + " SIMPLY DROPPING ITEMS THEN TURNING THE PLUGIN ON WILL RESULT IN THE DROPPED ITEMS BEING ROLLED."
                            + " SELL YOUR STUFF FIRST",
                    "Chance Man - Tutorial Island",
                    JOptionPane.WARNING_MESSAGE
            );

            pluginManager.setPluginEnabled(plugin, false);
            try {
                pluginManager.stopPlugin(plugin);
            } catch (PluginInstantiationException ignored) {}
        });
    }
}

package com.chanceman.persist;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import net.runelite.client.config.ConfigManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.lang.reflect.Type;
import java.util.LinkedHashSet;
import java.util.Set;

/**
 * Mirrors ChanceMan state into RuneLite ConfigManager so it can sync across machines
 * via RuneLite's profile/cloud sync.
 * Uses stamped read/write: each set is stored with a last-write timestamp
 * to support last-writer-wins (LWW) reconciliation across machines.
 */
@Singleton
public final class ConfigPersistence
{
    private static final String GROUP = "chanceman";
    private static final String DATA_SUFFIX = ".data";
    private static final String TS_SUFFIX = ".ts";
    private static final Type SET_TYPE = new TypeToken<Set<Integer>>(){}.getType();

    private final ConfigManager configManager;
    private final Gson gson;

    @Inject
    public ConfigPersistence(ConfigManager configManager, Gson gson)
    {
        this.configManager = configManager;
        this.gson = gson;
    }
    private static String dataKey(String key, String player) { return key + "." + player + DATA_SUFFIX; }
    private static String tsKey(String key, String player)   { return key + "." + player + TS_SUFFIX; }
    /** Value class for stamped set reads. */
    public static final class StampedSet
    {
        public final Set<Integer> data;
        public final long ts; // epoch millis; 0 means "unknown/not set"

        public StampedSet(Set<Integer> data, long ts)
        {
            this.data = (data != null) ? new LinkedHashSet<>(data) : new LinkedHashSet<>();
            this.ts = Math.max(0L, ts);
        }
    }

    /**
     * Read a stamped set from ConfigManager.
     * Returns empty set + ts=0 if absent or malformed.
     */
    public StampedSet readStampedSet(String player, String key)
    {
        if (isBlank(player) || isBlank(key))
        {
            return new StampedSet(new LinkedHashSet<>(), 0L);
        }

        String rawData = configManager.getConfiguration(GROUP, dataKey(key, player));
        String rawTs   = configManager.getConfiguration(GROUP, tsKey(key, player));

        if (isBlank(rawData) || isBlank(rawTs))
        {
            return new StampedSet(new LinkedHashSet<>(), 0L);
        }

        try
        {
            Set<Integer> parsed = gson.fromJson(rawData, SET_TYPE);
            long ts = parseLongSafe(rawTs);
            return new StampedSet((parsed != null) ? parsed : new LinkedHashSet<>(), ts);
        }
        catch (Exception ignored)
        {
            return new StampedSet(new LinkedHashSet<>(), 0L);
        }
    }

    /**
     * Write a stamped set to ConfigManager (unconditional).
     *
     * @param timestampMillis epoch millis representing the authoritative write time
     */
    public void writeStampedSet(String player, String key, Set<Integer> data, long timestampMillis)
    {
        if (isBlank(player) || isBlank(key)) return;

        String dataJson = gson.toJson((data != null) ? data : new LinkedHashSet<>());
        String tsStr    = String.valueOf(Math.max(0L, timestampMillis));

        // Two separate keys: value and timestamp
        configManager.setConfiguration(GROUP, dataKey(key, player), dataJson);
        configManager.setConfiguration(GROUP, tsKey(key, player), tsStr);
    }

    /**
     * Write only if the provided timestamp is >= the currently stored timestamp.
     * This is a simple guard against out-of-order writes when multiple machines
     * or threads may be updating the cloud state.
     *
     * @return true if a write occurred, false if skipped
     */
    public boolean writeStampedSetIfNewer(String player, String key, Set<Integer> data, long timestampMillis)
    {
        if (isBlank(player) || isBlank(key)) return false;

        long existingTs = parseLongSafe(configManager.getConfiguration(GROUP, tsKey(key, player)));
        if (timestampMillis < existingTs)
        {
            // Skip stale write
            return false;
        }
        writeStampedSet(player, key, data, timestampMillis);
        return true;
    }

    private static boolean isBlank(String s) { return s == null || s.isEmpty(); }

    private static long parseLongSafe(String s)
    {
        if (isBlank(s)) return 0L;
        try { return Long.parseLong(s.trim()); } catch (NumberFormatException e) { return 0L; }
    }
}

package com.chanceman.rolls;

import com.chanceman.ChanceManConfig;
import com.chanceman.account.AccountManager;
import net.runelite.client.config.ConfigManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ThreadLocalRandom;

@Singleton
public final class RollPoolManager
{
    private static final String CONFIG_GROUP = "chanceman";
    private static final String TOOL_COUNTER_KEY = "toolRollsSinceLastTool.";
    private static final String QUEST_MISS_KEY = "questItemMissStreak.";

    private final ChanceManConfig config;
    private final ConfigManager configManager;
    private final AccountManager accountManager;

    private int rollsSinceTool;
    private int questMissStreak;

    @Inject
    public RollPoolManager(
            ChanceManConfig config,
            ConfigManager configManager,
            AccountManager accountManager)
    {
        this.config = config;
        this.configManager = configManager;
        this.accountManager = accountManager;
    }

    public synchronized List<Integer> selectPool(
            Set<Integer> allTradeableItems,
            Set<Integer> rolledItems,
            boolean toolGuaranteeEnabled,
            boolean questItemRollsEnabled)
    {
        if (allTradeableItems == null || allTradeableItems.isEmpty())
        {
            return Collections.emptyList();
        }

        List<Integer> available = new ArrayList<>(allTradeableItems.size());
        for (int itemId : allTradeableItems)
        {
            if (rolledItems == null || !rolledItems.contains(itemId))
            {
                available.add(itemId);
            }
        }

        if (available.isEmpty())
        {
            return Collections.emptyList();
        }

        if (toolGuaranteeEnabled
                && rollsSinceTool >= getToolGuaranteeInterval() - 1)
        {
            List<Integer> tools = new ArrayList<>();
            for (int itemId : available)
            {
                if (RollItemPools.isToolItem(itemId))
                {
                    tools.add(itemId);
                }
            }

            if (!tools.isEmpty())
            {
                return tools;
            }
        }

        if (!questItemRollsEnabled)
        {
            return available;
        }

        List<Integer> questItems = new ArrayList<>();
        List<Integer> normalItems = new ArrayList<>();
        for (int itemId : available)
        {
            if (RollItemPools.isQuestItem(itemId))
            {
                questItems.add(itemId);
            }
            else
            {
                normalItems.add(itemId);
            }
        }

        if (!questItems.isEmpty()
                && ThreadLocalRandom.current().nextInt(100) < getQuestItemChance())
        {
            return questItems;
        }

        return normalItems.isEmpty() ? questItems : normalItems;
    }

    public synchronized void recordCompletedRoll(
            int itemId,
            boolean toolGuaranteeEnabled,
            boolean questItemRollsEnabled)
    {
        if (!toolGuaranteeEnabled && !questItemRollsEnabled)
        {
            return;
        }

        if (toolGuaranteeEnabled)
        {
            rollsSinceTool = RollItemPools.isToolItem(itemId)
                    ? 0
                    : increment(rollsSinceTool);
        }

        if (questItemRollsEnabled)
        {
            questMissStreak = RollItemPools.isQuestItem(itemId)
                    ? 0
                    : increment(questMissStreak);
        }

        saveState(toolGuaranteeEnabled, questItemRollsEnabled);
    }

    public synchronized void loadState()
    {
        rollsSinceTool = 0;
        questMissStreak = 0;

        String player = accountManager.getPlayerName();
        if (player == null || player.isEmpty())
        {
            return;
        }

        rollsSinceTool = readCounter(TOOL_COUNTER_KEY + player);
        questMissStreak = readCounter(QUEST_MISS_KEY + player);
    }

    private int getToolGuaranteeInterval()
    {
        return Math.max(1, Math.min(1000, config.toolRollGuaranteeInterval()));
    }

    private int getQuestItemChance()
    {
        int startingChance = clampPercent(config.questItemStartingChance());
        int chanceIncrease = clampPercent(config.questItemChanceIncrease());
        int maximumChance = clampPercent(config.questItemMaximumChance());
        long chance = (long) startingChance + (long) questMissStreak * chanceIncrease;
        return (int) Math.min(maximumChance, chance);
    }

    private int readCounter(String key)
    {
        String value = configManager.getConfiguration(CONFIG_GROUP, key);
        if (value == null || value.isEmpty())
        {
            return 0;
        }

        try
        {
            return Math.max(0, Integer.parseInt(value.trim()));
        }
        catch (NumberFormatException ignored)
        {
            return 0;
        }
    }

    private void saveState(boolean toolGuaranteeEnabled, boolean questItemRollsEnabled)
    {
        String player = accountManager.getPlayerName();
        if (player == null || player.isEmpty())
        {
            return;
        }

        if (toolGuaranteeEnabled)
        {
            configManager.setConfiguration(
                    CONFIG_GROUP,
                    TOOL_COUNTER_KEY + player,
                    String.valueOf(rollsSinceTool)
            );
        }

        if (questItemRollsEnabled)
        {
            configManager.setConfiguration(
                    CONFIG_GROUP,
                    QUEST_MISS_KEY + player,
                    String.valueOf(questMissStreak)
            );
        }
    }

    private static int clampPercent(int value)
    {
        return Math.max(0, Math.min(100, value));
    }

    private static int increment(int value)
    {
        return value == Integer.MAX_VALUE ? value : value + 1;
    }
}

package com.chanceman.ui;

import com.chanceman.drops.DropCache;
import lombok.extern.slf4j.Slf4j;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.events.MenuOpened;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
public class DropsMenuListener
{
    private final Client client;
    private final ClientThread clientThread;
    private final DropCache dropCache;
    private final MusicWidgetController widgetController;

    @Inject
    public DropsMenuListener(
            Client client,
            ClientThread clientThread,
            DropCache dropCache,
            MusicWidgetController widgetController
    )
    {
        this.client = client;
        this.clientThread = clientThread;
        this.dropCache = dropCache;
        this.widgetController = widgetController;
    }

    @Subscribe
    public void onMenuOpened(MenuOpened event)
    {
        List<MenuEntry> entries = new ArrayList<>(Arrays.asList(event.getMenuEntries()));
        NPC target = null;
        MenuEntry attackEntry = null;
        int attackIdx = -1;

        for (int i = 0; i < entries.size(); i++)
        {
            MenuEntry e = entries.get(i);
            if (e.getType() == MenuAction.NPC_SECOND_OPTION && "Attack".equals(e.getOption()))
            {
                try
                {
                    NPC possible = client.getTopLevelWorldView()
                            .npcs()
                            .byIndex(e.getIdentifier());
                    if (possible != null && possible.getCombatLevel() > 0)
                    {
                        target = possible;
                        attackEntry = e;
                        attackIdx = i;
                        break;
                    }
                }
                catch (ArrayIndexOutOfBoundsException ex)
                {
                    // ignore invalid indices
                }
            }
        }
        if (attackEntry == null || target == null)
        {
            return;
        }

        int id = target.getId();
        String name = target.getName();
        int level = target.getCombatLevel();

        MenuEntry showDrops = WidgetUtils.createShowDropsEntry(
                client,
                attackIdx - 1,
                attackEntry
        );
        showDrops.onClick(me -> fetchAndDisplayDrops(id, name, level, 1));

        entries.add(attackIdx + 1, showDrops);
        event.setMenuEntries(entries.toArray(new MenuEntry[0]));
    }
    private void fetchAndDisplayDrops(int id, String name, int level, int attemptsLeft)
    {
        dropCache.get(id, name, level)
                .whenComplete((dropData, ex) ->
                {
                    if (dropData != null && ex == null)
                    {
                        clientThread.invokeLater(() -> widgetController.override(dropData));
                        return;
                    }

                    if (attemptsLeft > 0) fetchAndDisplayDrops(id, name, level, attemptsLeft - 1);
                    else log.error("Failed to fetch drop data for {}", name, ex);

                });
    }
}

