package com.chanceman.ui;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.FontMetrics;
import java.awt.Color;
import java.awt.Rectangle;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;

import com.chanceman.drops.DropItem;

import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Overlay that displays item name tooltips when hovering drop icons
 * injected into the music tab by {@link MusicWidgetController}.
 */
@Singleton
public class DropsTooltipOverlay extends Overlay
{
    private final Client client;
    private final MusicWidgetController widgetController;

    @Inject
    public DropsTooltipOverlay(
            Client client,
            MusicWidgetController widgetController
    )
    {
        this.client = client;
        this.widgetController = widgetController;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!widgetController.isOverrideActive()) {return null;}

        Point mouse = client.getMouseCanvasPosition();
        for (Map.Entry<Widget, DropItem> entry : widgetController.getIconItemMap().entrySet())
        {
            Widget w = entry.getKey();
            if (w == null || w.isHidden()) {continue;}
            Rectangle bounds = w.getBounds();
            if (bounds.contains(mouse.getX(), mouse.getY()))
            {
                DropItem drop = entry.getValue();
                drawTooltip(graphics, drop.getName(), drop.getOneOverRarity(), mouse);
                break;
            }
        }
        return null;
    }

    private void drawTooltip(Graphics2D g, String name, String rarity, Point mouse)
    {
        FontMetrics fm = g.getFontMetrics();
        int padding = 4;
        int gap = 2;
        int lineH  = fm.getHeight();

        String rateText = "Rate: " + rarity;

        int nameW = fm.stringWidth(name);
        int rateW = fm.stringWidth(rateText);

        int nameBoxW = nameW + padding * 2;
        int rateBoxW = rateW + padding * 2;
        int boxH     = lineH + padding * 2;
        int totalH   = boxH * 2 + gap;
        int clampW   = Math.max(nameBoxW, rateBoxW);

        int x = mouse.getX() + 10;
        int y = mouse.getY() - 10;

        Rectangle clip = g.getClipBounds();
        x = Math.max(clip.x, Math.min(x, clip.x + clip.width  - clampW));
        y = Math.max(clip.y + totalH, Math.min(y, clip.y + clip.height));

        int nameTop = y - totalH;
        drawBox(g, x, nameTop, nameBoxW, boxH);
        drawBox(g, x, y - boxH, rateBoxW, boxH);

        g.setColor(Color.WHITE);
        int base = nameTop + padding + fm.getAscent();
        g.drawString(name, x + padding, base);

        int rateBase = y - boxH + padding + fm.getAscent();
        String prefix = "Rate: ";
        int prefixW = fm.stringWidth(prefix);

        g.setColor(Color.WHITE);
        g.drawString(prefix, x + padding, rateBase);

        g.setColor(Color.ORANGE);
        g.drawString(rarity, x + padding + prefixW, rateBase);
    }

    private void drawBox(Graphics2D g, int x, int y, int w, int h)
    {
        g.setColor(new Color(0, 0, 0, 100));
        g.fillRect(x, y, w, h);
        g.setColor(new Color(50, 50, 50, 200));
        g.drawRect(x, y, w, h);
    }
}

package com.chanceman.ui;

import com.chanceman.filters.EnsouledHeadMapping;
import com.chanceman.managers.RolledItemsManager;
import com.chanceman.menus.EnabledUI;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

@Singleton
public class ItemDimmerController extends Overlay
{
    private static final int COLLECTION_LOG_GROUP = 621;
    private static final int[] NO_RELATED_IDS = new int[0];

    private final Client client;
    private final RolledItemsManager rolledItemsManager;
    private final ItemManager itemManager;

    private final List<Widget> itemWidgets = new ArrayList<>();
    private final Set<Widget> itemWidgetSet =
            java.util.Collections.newSetFromMap(new IdentityHashMap<>());

    private final Map<Integer, Integer> canonicalIdCache = new HashMap<>(256);
    private final Map<Integer, int[]> relatedIdsCache = new HashMap<>(256);
    private final Map<Integer, Boolean> dimDecisionCache = new HashMap<>(256);
    private final Map<Integer, Boolean> groupDimmingCache = new HashMap<>(32);

    private volatile Set<Integer> allTradeableItems = Set.of();
    private volatile int dimOpacity = 150;
    private volatile boolean enabled = true;
    private volatile boolean rebuildNeeded = true;
    private volatile int stateVersion = 0;

    private int appliedStateVersion = -1;

    @Inject
    public ItemDimmerController(
            Client client,
            RolledItemsManager rolledItemsManager,
            ItemManager itemManager)
    {
        this.client = client;
        this.rolledItemsManager = rolledItemsManager;
        this.itemManager = itemManager;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.UNDER_WIDGETS);
        setPriority(PRIORITY_HIGH);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!enabled || client.getGameState() != GameState.LOGGED_IN)
        {
            return null;
        }

        if (rebuildNeeded)
        {
            rebuildItemWidgetCache();
        }

        if (appliedStateVersion != stateVersion)
        {
            dimDecisionCache.clear();
            appliedStateVersion = stateVersion;
        }

        for (int i = 0; i < itemWidgets.size(); i++)
        {
            applyDimming(itemWidgets.get(i));
        }

        return null;
    }

    public void setAllTradeableItems(Set<Integer> allTradeableItems)
    {
        this.allTradeableItems = allTradeableItems == null || allTradeableItems.isEmpty()
                ? Set.of()
                : Set.copyOf(allTradeableItems);

        invalidateState();
        rebuildNeeded = true;
    }

    public void setEnabled(boolean enabled)
    {
        if (this.enabled == enabled)
        {
            return;
        }

        this.enabled = enabled;
        invalidateState();

        if (enabled)
        {
            rebuildNeeded = true;
        }
        else
        {
            restoreItemWidgets();
        }
    }

    public void setDimOpacity(int opacity)
    {
        dimOpacity = Math.max(0, Math.min(255, opacity));
    }

    public void invalidateState()
    {
        stateVersion++;
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        rebuildNeeded = true;
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        rebuildNeeded = true;
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed event)
    {
        rebuildNeeded = true;
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event)
    {
        switch (event.getScriptId())
        {
            case ScriptID.INVENTORY_DRAWITEM:
            case ScriptID.INTERFACE_INV_DRAW_SLOT_BIG:
                cacheItemWidget(client.getScriptActiveWidget());
                break;

            case ScriptID.BANKMAIN_BUILD:
            case ScriptID.BANKMAIN_FINISHBUILDING:
            case ScriptID.BANKMAIN_SEARCH_REFRESH:
            case ScriptID.BANK_DEPOSITBOX_INIT:
            case ScriptID.GROUP_IRONMAN_STORAGE_BUILD:
            case ScriptID.RAIDS_STORAGE_PRIVATE_ITEMS:
            case ScriptID.SEED_VAULT_BUILD:
                rebuildNeeded = true;
                break;

            default:
                break;
        }
    }

    private void rebuildItemWidgetCache()
    {
        itemWidgets.clear();
        itemWidgetSet.clear();
        groupDimmingCache.clear();

        Widget[] roots = client.getWidgetRoots();
        if (roots != null)
        {
            for (Widget root : roots)
            {
                collectItemWidgets(root);
            }
        }

        rebuildNeeded = false;
    }

    private void collectItemWidgets(Widget widget)
    {
        if (widget == null || widget.isHidden())
        {
            return;
        }

        if ((widget.getId() >>> 16) == COLLECTION_LOG_GROUP)
        {
            return;
        }

        if (widget.getItemId() > 0)
        {
            cacheItemWidget(widget);
        }

        Widget[] dynamicChildren = widget.getDynamicChildren();
        if (dynamicChildren != null)
        {
            for (Widget child : dynamicChildren)
            {
                collectItemWidgets(child);
            }
        }

        Widget[] staticChildren = widget.getStaticChildren();
        if (staticChildren != null)
        {
            for (Widget child : staticChildren)
            {
                collectItemWidgets(child);
            }
        }

        Widget[] nestedChildren = widget.getNestedChildren();
        if (nestedChildren != null)
        {
            for (Widget child : nestedChildren)
            {
                collectItemWidgets(child);
            }
        }
    }

    private void cacheItemWidget(Widget widget)
    {
        if (widget == null || widget.getItemId() <= 0)
        {
            return;
        }

        if ((widget.getId() >>> 16) == COLLECTION_LOG_GROUP)
        {
            return;
        }

        if (itemWidgetSet.add(widget))
        {
            itemWidgets.add(widget);
        }
    }

    private void applyDimming(Widget widget)
    {
        if (widget == null || widget.isHidden())
        {
            return;
        }

        int itemId = widget.getItemId();
        if (itemId <= 0)
        {
            return;
        }

        if (isBankPlaceholderWidget(widget))
        {
            return;
        }

        int groupId = widget.getId() >>> 16;

        if (!shouldDimGroup(groupId))
        {
            if (widget.getOpacity() != 0)
            {
                widget.setOpacity(0);
            }

            return;
        }

        int target = shouldDim(itemId) ? dimOpacity : 0;

        if (widget.getOpacity() != target)
        {
            widget.setOpacity(target);
        }
    }

    private boolean shouldDimGroup(int groupId)
    {
        Boolean cached = groupDimmingCache.get(groupId);
        if (cached != null)
        {
            return cached;
        }

        EnabledUI ui = EnabledUI.fromGroupId(groupId);
        boolean result = ui == null || ui.isGreyLockedItems();

        groupDimmingCache.put(groupId, result);
        return result;
    }

    private boolean shouldDim(int rawItemId)
    {
        int mappedItemId = EnsouledHeadMapping.toTradeableId(rawItemId);
        int canonicalItemId = canonicalize(mappedItemId);

        if (canonicalItemId <= 0)
        {
            return false;
        }

        Boolean cached = dimDecisionCache.get(canonicalItemId);
        if (cached != null)
        {
            return cached;
        }

        boolean result = allTradeableItems.contains(canonicalItemId)
                && !isRolled(mappedItemId, canonicalItemId);

        dimDecisionCache.put(canonicalItemId, result);
        return result;
    }

    private int canonicalize(int itemId)
    {
        Integer cached = canonicalIdCache.get(itemId);
        if (cached != null)
        {
            return cached;
        }

        int canonicalItemId;

        try
        {
            canonicalItemId = itemManager.canonicalize(itemId);
        }
        catch (Exception e)
        {
            canonicalItemId = itemId;
        }

        canonicalIdCache.put(itemId, canonicalItemId);
        return canonicalItemId;
    }

    private boolean isRolled(int normalizedItemId, int canonicalItemId)
    {
        if (normalizedItemId > 0
                && rolledItemsManager.isRolled(normalizedItemId))
        {
            return true;
        }

        if (canonicalItemId > 0
                && canonicalItemId != normalizedItemId
                && rolledItemsManager.isRolled(canonicalItemId))
        {
            return true;
        }

        for (int relatedId : getRelatedIds(normalizedItemId))
        {
            if (rolledItemsManager.isRolled(relatedId))
            {
                return true;
            }
        }

        if (canonicalItemId != normalizedItemId)
        {
            for (int relatedId : getRelatedIds(canonicalItemId))
            {
                if (rolledItemsManager.isRolled(relatedId))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private int[] getRelatedIds(int itemId)
    {
        if (itemId <= 0)
        {
            return NO_RELATED_IDS;
        }

        int[] cached = relatedIdsCache.get(itemId);
        if (cached != null)
        {
            return cached;
        }

        int[] relatedIds = NO_RELATED_IDS;

        try
        {
            ItemComposition composition = itemManager.getItemComposition(itemId);

            if (composition != null)
            {
                int placeholderId = composition.getPlaceholderTemplateId() != -1
                        ? composition.getPlaceholderId()
                        : -1;

                int linkedNoteId = composition.getLinkedNoteId();

                boolean hasPlaceholder = placeholderId > 0
                        && placeholderId != itemId;

                boolean hasLinkedNote = linkedNoteId > 0
                        && linkedNoteId != itemId
                        && linkedNoteId != placeholderId;

                if (hasPlaceholder && hasLinkedNote)
                {
                    relatedIds = new int[]{placeholderId, linkedNoteId};
                }
                else if (hasPlaceholder)
                {
                    relatedIds = new int[]{placeholderId};
                }
                else if (hasLinkedNote)
                {
                    relatedIds = new int[]{linkedNoteId};
                }
            }
        }
        catch (Exception ignored)
        {
        }

        relatedIdsCache.put(itemId, relatedIds);
        return relatedIds;
    }

    private void restoreItemWidgets()
    {
        for (int i = 0; i < itemWidgets.size(); i++)
        {
            Widget widget = itemWidgets.get(i);

            if (widget != null
                    && widget.getItemId() > 0
                    && !isBankPlaceholderWidget(widget)
                    && widget.getOpacity() != 0)
            {
                widget.setOpacity(0);
            }
        }
    }

    private boolean isBankPlaceholderWidget(Widget widget)
    {
        return widget.getItemId() > 0
                && widget.getItemQuantity() == 0;
    }
}

package com.chanceman.ui;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;

import net.runelite.api.Client;
import net.runelite.api.SpritePixels;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.ImageUtil;

/**
 * Caches custom item sprites scaled for widget display.
 */
@Singleton
public class ItemSpriteCache
{
    private static final int ICON_SIZE = 32;

    private final ItemManager itemManager;
    private final Client client;
    private final Map<Integer, Integer> spriteIds = new HashMap<>();
    private int nextGeneratedSpriteId = 0x10000;

    @Inject
    public ItemSpriteCache(ItemManager itemManager, Client client)
    {
        this.itemManager = itemManager;
        this.client = client;
    }

    private int generateNextId()
    {
        return nextGeneratedSpriteId++;
    }

    /**
     * Returns a sprite ID for the given item
     */
    public int getSpriteId(int itemId)
    {
        return spriteIds.computeIfAbsent(itemId, id ->
        {
            BufferedImage img = itemManager.getImage(id, 1, false);
            if (img == null)
            {
                return -1;
            }

            // resize to ICON_SIZE x ICON_SIZE
            BufferedImage resized = ImageUtil.resizeImage(img, ICON_SIZE, ICON_SIZE);

            // convert to SpritePixels for the client's override map
            SpritePixels pixels = ImageUtil.getImageSpritePixels(resized, client);

            // generate a unique sprite ID and register the override
            int spriteId = generateNextId();
            client.getSpriteOverrides().put(spriteId, pixels);

            return spriteId;
        });
    }

    /**
     * Clears all cached sprites and unregisters them from the client's override map.
     */
    public void clear()
    {
        spriteIds.values().forEach(client.getSpriteOverrides()::remove);
        spriteIds.clear();
        nextGeneratedSpriteId = 0x10000;
    }
}

package com.chanceman.ui;

import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class MusicSearchButton
{
    private static final int MUSIC_GROUP =
            InterfaceID.Music.UNIVERSE >>> 16;

    private static final int SPRITE_SEARCH = 1970;

    private static final int W = 14;
    private static final int H = 14;
    private static final int GAP = 4;
    private static final int NUDGE_LEFT = 26;
    private static final int NUDGE_DOWN = 0;

    private static final int PLACE_ATTEMPTS = 4;

    private final Client client;
    private final ClientThread clientThread;
    private final MusicWidgetController musicWidgetController;

    private Widget icon;
    private boolean running;

    @Getter
    private boolean overrideActive;

    @Inject
    public MusicSearchButton(
            Client client,
            ClientThread clientThread,
            MusicWidgetController musicWidgetController)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.musicWidgetController = musicWidgetController;
    }

    public void onStart()
    {
        running = true;
        requestPlacement();
    }

    public void onStop()
    {
        running = false;
        overrideActive = false;

        clientThread.invokeLater(() ->
        {
            hide();
            icon = null;
        });
    }

    public void onOverrideActivated()
    {
        overrideActive = true;

        clientThread.invokeLater(
                this::hide
        );
    }

    public void onOverrideDeactivated()
    {
        overrideActive = false;

        if (running)
        {
            requestPlacement();
        }
    }

    public void invalidate()
    {
        icon = null;
    }

    @Subscribe
    public void onWidgetLoaded(
            WidgetLoaded event)
    {
        if (event.getGroupId()
                != MUSIC_GROUP)
        {
            return;
        }

        invalidate();

        if (running)
        {
            requestPlacement();
        }
    }

    private void requestPlacement()
    {
        placeSearchIcon(
                PLACE_ATTEMPTS
        );
    }

    private void placeSearchIcon(
            int attemptsRemaining)
    {
        clientThread.invokeLater(() ->
        {
            if (!running
                    || overrideActive)
            {
                hide();
                return;
            }

            if (!placeSearchIconInternal()
                    && attemptsRemaining > 1)
            {
                placeSearchIcon(
                        attemptsRemaining - 1
                );
            }
        });
    }

    public void placeSearchIcon()
    {
        if (!client.isClientThread())
        {
            requestPlacement();
            return;
        }

        placeSearchIconInternal();
    }

    private boolean placeSearchIconInternal()
    {
        if (!running
                || overrideActive)
        {
            hide();
            return false;
        }

        Widget contents =
                client.getWidget(
                        InterfaceID.Music.CONTENTS
                );

        Widget frame =
                client.getWidget(
                        InterfaceID.Music.FRAME
                );

        if (contents == null
                || frame == null)
        {
            return false;
        }

        Widget root =
                client.getWidget(
                        InterfaceID.Music.UNIVERSE
                );

        Widget toggleAll =
                findByAction(
                        root,
                        "Toggle all"
                );

        int x;
        int y;

        if (toggleAll != null)
        {
            x = toggleAll.getOriginalX()
                    - W
                    - GAP
                    - NUDGE_LEFT;

            y = toggleAll.getOriginalY()
                    + (toggleAll.getOriginalHeight() - H) / 2
                    + NUDGE_DOWN;
        }
        else
        {
            int frameRight =
                    frame.getOriginalX()
                            + frame.getOriginalWidth();

            x = frameRight
                    - W
                    - (GAP + 10)
                    - NUDGE_LEFT;

            y = Math.max(
                    6,
                    frame.getOriginalY()
                            - H
                            - GAP
            ) + NUDGE_DOWN;
        }

        /*
         * A Music interface rebuild can create a new widget tree with the same
         * parent ID, so verify that the cached icon object is actually still
         * present in the current parent's children.
         */
        if (!isCurrentIcon(contents))
        {
            icon = findExistingIcon(
                    contents
            );
        }

        if (icon == null)
        {
            icon = contents.createChild(
                    -1,
                    WidgetType.GRAPHIC
            );

            icon.setHasListener(true);
            icon.setAction(
                    0,
                    "Search Drops"
            );

            icon.setOnOpListener(
                    (JavaScriptCallback) event ->
                            musicWidgetController.openDropsSearch()
            );
        }

        icon.setHidden(false);
        icon.setSpriteId(
                SPRITE_SEARCH
        );

        move(
                icon,
                x,
                y,
                W,
                H
        );

        icon.revalidate();

        return true;
    }

    public void hide()
    {
        if (icon != null)
        {
            icon.setHidden(true);
        }
    }

    private boolean isCurrentIcon(
            Widget contents)
    {
        if (icon == null
                || icon.getParentId()
                != contents.getId())
        {
            return false;
        }

        Widget[] children =
                contents.getDynamicChildren();

        if (children == null)
        {
            return false;
        }

        for (Widget child : children)
        {
            if (child == icon)
            {
                return true;
            }
        }

        return false;
    }

    private Widget findExistingIcon(
            Widget contents)
    {
        Widget[] children =
                contents.getDynamicChildren();

        if (children == null)
        {
            return null;
        }

        for (Widget child : children)
        {
            if (child == null)
            {
                continue;
            }

            if (child.getSpriteId()
                    == SPRITE_SEARCH
                    && hasAction(
                    child,
                    "Search Drops"))
            {
                return child;
            }
        }

        return null;
    }

    private void move(
            Widget widget,
            int x,
            int y,
            int width,
            int height)
    {
        widget.setOriginalX(x);
        widget.setOriginalY(y);
        widget.setOriginalWidth(width);
        widget.setOriginalHeight(height);

        widget.setXPositionMode(
                WidgetPositionMode.ABSOLUTE_LEFT
        );

        widget.setYPositionMode(
                WidgetPositionMode.ABSOLUTE_TOP
        );
    }

    private Widget findByAction(
            Widget parent,
            String action)
    {
        if (parent == null)
        {
            return null;
        }

        if (hasAction(
                parent,
                action))
        {
            return parent;
        }

        Widget found =
                findByAction(
                        parent.getStaticChildren(),
                        action
                );

        if (found != null)
        {
            return found;
        }

        found =
                findByAction(
                        parent.getDynamicChildren(),
                        action
                );

        if (found != null)
        {
            return found;
        }

        return findByAction(
                parent.getNestedChildren(),
                action
        );
    }

    private Widget findByAction(
            Widget[] children,
            String action)
    {
        if (children == null)
        {
            return null;
        }

        for (Widget child : children)
        {
            Widget found =
                    findByAction(
                            child,
                            action
                    );

            if (found != null)
            {
                return found;
            }
        }

        return null;
    }

    private static boolean hasAction(
            Widget widget,
            String action)
    {
        String[] actions =
                widget.getActions();

        if (actions == null)
        {
            return false;
        }

        for (String widgetAction : actions)
        {
            if (widgetAction != null
                    && widgetAction.equalsIgnoreCase(
                    action))
            {
                return true;
            }
        }

        return false;
    }
}

package com.chanceman.ui;

import com.chanceman.ChanceManConfig;
import com.chanceman.drops.DropItem;
